window.ANSWER_TERMS = {"endocriene signalering":{"title":"Endocriene signalering","short":"Klieren geven hormonen af aan het bloed, dat ze naar verre doelorganen vervoert.","definition":"<p>Bij <b>endocriene signalering</b> scheiden endocriene klieren hormonen rechtstreeks in de bloedbaan uit.</p><p>Via het bloed bereiken de hormonen doelcellen elders in het lichaam die de bijbehorende receptor dragen. Het effect is trager maar wijdverbreid.</p>","image_url":"","wiki_title":"Endocrine system","match":"endocriene signalering|endocrien|endocriene secretie|endocriene celsignalering"},"cholesterol":{"title":"Cholesterol","short":"Vetachtige stof die de celmembraan stevigheid en de juiste vloeibaarheid geeft en grondstof is voor steroïden.","definition":"<p><b>Cholesterol</b> is een steroïd dat tussen de fosfolipiden van de celmembraan zit en de membraanvloeibaarheid stabiliseert.</p><p>Het is bovendien de grondstof voor steroïdhormonen, vitamine D en galzouten.</p>","image_url":"","wiki_title":"Cholesterol","match":"cholesterol"},"melanine":{"title":"Melanine","short":"Bruinzwart pigment dat de huid kleurt en tegen UV-straling beschermt.","definition":"<p><b>Melanine</b> wordt in melanocyten gevormd uit tyrosine (met het enzym tyrosinase) en opgeslagen in melanosomen.</p><p>Het absorbeert UV-straling en beschermt zo het DNA van de huidcellen. Er bestaan een bruinzwarte (eumelanine) en een roodgele (feomelanine) variant.</p>","image_url":"","wiki_title":"Melanin","match":"melanine"},"macrofaag":{"title":"Macrofaag","short":"Grote fagocyt in de weefsels die pathogenen en celresten opruimt en antigenen presenteert.","definition":"<p>De <b>macrofaag</b> ontstaat uit een monocyt die het weefsel is binnengegaan. Hij fagocyteert bacteriën, dode cellen en afval.</p><p>Als antigeenpresenterende cel activeert hij ook T-cellen en scheidt hij ontstekingsmediatoren uit. In de huid heten verwante cellen histiocyten.</p>","image_url":"","wiki_title":"Macrophage","match":"macrofaag|macrofagen"},"macula":{"title":"Macula","short":"Vlakke, niet-voelbare huidverandering die alleen in kleur verschilt (een 'vlek').","definition":"<p>Een <b>macula</b> is een plat, met de vinger niet-voelbaar plekje dat zich alleen door kleur onderscheidt van de omgeving.</p><p>Voorbeelden zijn een sproet of een café-au-lait-vlek. Wordt hij groter dan ~1 cm, dan spreekt men van een patch.</p>","image_url":"","wiki_title":"Skin condition","match":"macula|maculae"},"nodulus":{"title":"Nodulus","short":"Vaste, verheven en voelbare knobbel die dieper in de huid reikt dan een papel (> ~1 cm).","definition":"<p>Een <b>nodulus</b> (nodus, knobbel) is een stevige, verheven laesie die groter is dan een papel en dieper in de dermis of subcutis reikt.</p><p>Voorbeelden zijn een dermatofibroom of sommige huidtumoren.</p>","image_url":"","wiki_title":"Nodule (medicine)","match":"nodulus|nodus|noduli|nodi"},"ulcus":{"title":"Ulcus","short":"Diep huiddefect tot in de dermis of dieper, dat met een litteken geneest (een 'zweer').","definition":"<p>Een <b>ulcus</b> (zweer) is een dieper weefselverlies dat tot in de dermis of subcutis reikt.</p><p>Doordat de dermis is aangetast, geneest het met littekenvorming. Een ulcus cruris (open been) is een bekend voorbeeld.</p>","image_url":"","wiki_title":"Ulcer (dermatology)","match":"ulcus|ulcera"},"atrofie":{"title":"Atrofie","short":"Verdunning of afname van weefsel; bij de huid een dunnere, kwetsbaardere epidermis en/of dermis.","definition":"<p><b>Atrofie</b> is het slinken van een weefsel of orgaan doordat de cellen krimpen of in aantal afnemen.</p><p>Huidatrofie (bijv. na langdurig sterk corticosteroïdgebruik of door veroudering) geeft een dunne, doorschijnende, kwetsbare huid.</p>","image_url":"","wiki_title":"Atrophy","match":"atrofie"},"hersenstam":{"title":"Hersenstam","short":"De hersenstam (mesencephalon, pons, medulla oblongata) verbindt grote hersenen en ruggenmerg en bevat kernen van hersenzenuwen en centra voor ademhaling en circulatie.","definition":"<p>De <strong>hersenstam</strong> bestaat uit het mesencephalon (middenhersenen), de pons en de medulla oblongata. Alle opstijgende en afdalende banen tussen hersenen en ruggenmerg lopen erdoorheen.</p><p>Hij bevat de kernen van de hersenzenuwen III–XII, de formatio reticularis (bewustzijn, slaap-waakritme) en vitale centra voor ademhaling en hart- en vaatregulatie. Uitval van de hersenstam is daardoor snel levensbedreigend; hersenstamreflexen worden getest bij de vaststelling van hersendood.</p>","image_url":"","wiki_title":"Brainstem","match":"hersenstam|truncus cerebri|truncus encephali","option_only":true},"hypothalamus":{"title":"Hypothalamus","short":"De hypothalamus is het regelcentrum van de homeostase: hij stuurt hypofyse, autonoom zenuwstelsel, temperatuur, honger, dorst en circadiaan ritme.","definition":"<p>De <strong>hypothalamus</strong> is een klein deel van het diencephalon, onder de thalamus en rond de derde ventrikel. Hij is via het infundibulum verbonden met de hypofyse.</p><p>Hij maakt releasing- en inhibiting-hormonen (o.a. TRH, CRH, GnRH, GHRH, dopamine) die via het portale systeem de voorkwab sturen, en ADH en oxytocine die in de achterkwab worden afgegeven. Daarnaast regelt hij lichaamstemperatuur, honger en verzadiging, dorst, het slaap-waakritme (nucleus suprachiasmaticus) en het autonome zenuwstelsel.</p>","image_url":"","wiki_title":"Hypothalamus","match":"hypothalamus","option_only":true},"thalamus":{"title":"Thalamus","short":"De thalamus is het grote schakelstation in het diencephalon: vrijwel alle sensorische informatie (behalve reuk) wordt hier verwerkt op weg naar de cortex.","definition":"<p>De <strong>thalamus</strong> is een paarige, eivormige kern in het diencephalon aan weerszijden van de derde ventrikel. Hij bestaat uit veel subkernen met elk een eigen corticale projectie.</p><p>Sensorische banen (somatosensoriek via de VPL/VPM, zien via het corpus geniculatum laterale, horen via het corpus geniculatum mediale) schakelen hier om naar de cortex. Ook motorische lussen van basale kernen en cerebellum lopen via de thalamus, en hij speelt een rol bij bewustzijn en aandacht.</p>","image_url":"","wiki_title":"Thalamus","match":"thalamus","option_only":true},"globus pallidus pars externa":{"title":"Globus pallidus pars externa (GPe)","short":"De GPe is onderdeel van de basale kernen en vormt een schakel in de indirecte route; hij remt de nucleus subthalamicus.","definition":"<p>De <strong>globus pallidus pars externa</strong> is het laterale deel van de globus pallidus. Hij ontvangt remmende (GABA-erge) input van het striatum en stuurt zelf remmende projecties naar de nucleus subthalamicus.</p><p>Hij is een kernschakel van de <em>indirecte route</em> van de basale kernen (cortex → striatum → GPe → nucleus subthalamicus → GPi/SNr → thalamus), die beweging per saldo afremt.</p>","image_url":"","wiki_title":"Globus pallidus","match":"globus pallidus pars externa|gpe|globus pallidus externus|globus pallidus externa","option_only":true},"globus pallidus pars interna":{"title":"Globus pallidus pars interna (GPi)","short":"De GPi is de belangrijkste uitgangskern van de basale kernen; hij remt (GABA-erg) de motorische thalamus.","definition":"<p>De <strong>globus pallidus pars interna</strong> is samen met de substantia nigra pars reticulata de <em>uitgangskern</em> van de basale kernen. Hij geeft tonisch remmende GABA-erge output naar de motorische kernen van de thalamus.</p><p>De directe route (striatum → GPi) remt de GPi en ontremt zo de thalamus (meer beweging); de indirecte route versterkt via de nucleus subthalamicus juist de remming. De GPi is een doelwit bij diepe hersenstimulatie (o.a. dystonie, Parkinson).</p>","image_url":"","wiki_title":"Globus pallidus","match":"globus pallidus pars interna|gpi|globus pallidus internus|globus pallidus interna","option_only":true},"nucleus subthalamicus":{"title":"Nucleus subthalamicus","short":"De nucleus subthalamicus is een exciterende (glutamaterge) kern van de basale kernen in de indirecte route; laesie geeft hemiballisme.","definition":"<p>De <strong>nucleus subthalamicus</strong> ligt onder de thalamus, boven de substantia nigra. Het is de enige <em>exciterende</em> (glutamaterge) kern van de basale kernen.</p><p>Hij ontvangt remmende input van de GPe en prikkelt de GPi en substantia nigra pars reticulata, waardoor de thalamus sterker geremd wordt (indirecte route). Een laesie (bijv. een lacunair infarct) geeft contralateraal <em>hemiballisme</em>. Het is ook een doelwit voor diepe hersenstimulatie bij de ziekte van Parkinson.</p>","image_url":"","wiki_title":"Subthalamic nucleus","match":"nucleus subthalamicus|stn|subthalamische kern","option_only":true},"aquaductus cerebri":{"title":"Aquaductus cerebri","short":"De aquaductus cerebri is het nauwe kanaal in het mesencephalon dat de derde en vierde ventrikel verbindt.","definition":"<p>De <strong>aquaductus cerebri</strong> (van Sylvius) loopt door het mesencephalon en verbindt de <em>derde ventrikel</em> met de <em>vierde ventrikel</em>. Eromheen ligt de periaqueductale grijze stof.</p><p>Omdat hij zo nauw is, is het een typische plek voor obstructie (bijv. aangeboren stenose of een tumor in de pijnappelklierregio). Dat geeft een niet-communicerende hydrocephalus met verwijding van de laterale en derde ventrikels.</p>","image_url":"","wiki_title":"Cerebral aqueduct","match":"aquaductus cerebri|aqueductus cerebri|aquaduct van sylvius|aqueduct van sylvius","option_only":true},"laterale ventrikels":{"title":"Laterale ventrikels","short":"De laterale ventrikels zijn de twee grootste liquorholtes, één in elke hersenhelft; ze staan via de foramina van Monro in verbinding met de derde ventrikel.","definition":"<p>De <strong>laterale ventrikels</strong> liggen in de beide hemisferen van het telencephalon en hebben een C-vorm met een voorhoorn, lichaam, achterhoorn en onderhoorn (in de temporaalkwab).</p><p>Ze bevatten plexus choroideus, die liquor produceert. Via de foramina interventricularia (Monro) stroomt de liquor naar de derde ventrikel, daarna via de aquaductus naar de vierde ventrikel en de subarachnoïdale ruimte.</p>","image_url":"","wiki_title":"Lateral ventricles","match":"laterale ventrikels|laterale ventrikel|ventriculi laterales|zijventrikels","option_only":true},"canalis centralis":{"title":"Canalis centralis","short":"De canalis centralis is het smalle, met ependym beklede kanaal in het midden van het ruggenmerg; de voortzetting van de vierde ventrikel.","definition":"<p>De <strong>canalis centralis</strong> loopt door het midden van de grijze stof van het ruggenmerg en is een restant van het lumen van de neurale buis. Het is bekleed met ependymcellen en sluit aan op de vierde ventrikel.</p><p>Bij volwassenen is het kanaal vaak deels dichtgegroeid. Een abnormale verwijding heet hydromyelie; een holte in het ruggenmerg (syringomyelie) kan kruisende pijn- en temperatuurvezels beschadigen.</p>","image_url":"","wiki_title":"Central canal","match":"canalis centralis|centraal kanaal|centrale kanaal","option_only":true},"septum pellucidum":{"title":"Septum pellucidum","short":"Het septum pellucidum is een dun, doorschijnend tussenschot tussen de voorhoorns van de twee laterale ventrikels.","definition":"<p>Het <strong>septum pellucidum</strong> is een dunne, dubbele plaat van glia en zenuwvezels die in de mediaanlijn loopt tussen het corpus callosum (boven) en de fornix (onder). Het scheidt de voorhoorns van de linker en rechter laterale ventrikel.</p><p>Afwezigheid ervan komt voor bij ontwikkelingsstoornissen zoals septo-optische dysplasie; een holte tussen de twee bladen (cavum septi pellucidi) is meestal een normvariant.</p>","image_url":"","wiki_title":"Septum pellucidum","match":"septum pellucidum","option_only":true},"metencephalon":{"title":"Metencephalon","short":"Het metencephalon is het embryonale hersenblaasje waaruit de pons en het cerebellum ontstaan.","definition":"<p>Tijdens de ontwikkeling deelt het rhombencephalon (achterhersenen) zich in het <strong>metencephalon</strong> en het myelencephalon.</p><p>Uit het metencephalon ontstaan de <em>pons</em> en het <em>cerebellum</em>; het lumen wordt het bovenste deel van de vierde ventrikel. Uit het myelencephalon ontstaat de medulla oblongata.</p>","image_url":"","wiki_title":"Metencephalon","match":"metencephalon","option_only":true},"telencephalon":{"title":"Telencephalon","short":"Het telencephalon is het embryonale hersendeel waaruit de grote hersenhelften ontstaan: hersenschors, witte stof, basale kernen en de laterale ventrikels.","definition":"<p>Het prosencephalon (voorhersenen) deelt zich in het <strong>telencephalon</strong> en het diencephalon.</p><p>Uit het telencephalon ontstaan de twee cerebrale hemisferen met de cortex, de onderliggende witte stof, de basale kernen (striatum, globus pallidus), de amygdala en hippocampus, en de <em>laterale ventrikels</em> als holtes.</p>","image_url":"","wiki_title":"Cerebrum","match":"telencephalon|eindhersenen","option_only":true},"diencephalon":{"title":"Diencephalon","short":"Het diencephalon (tussenhersenen) omvat thalamus, hypothalamus, epithalamus (met epifyse) en subthalamus, rond de derde ventrikel.","definition":"<p>Het <strong>diencephalon</strong> ontstaat uit het achterste deel van het prosencephalon en ligt tussen de hemisferen en het mesencephalon. Het lumen is de <em>derde ventrikel</em>.</p><p>Belangrijke onderdelen: de <em>thalamus</em> (sensorisch schakelstation), de <em>hypothalamus</em> (homeostase, hypofysesturing), de epithalamus met de epifyse (melatonine) en de subthalamus. Ook de retina en de n. opticus ontstaan als uitstulping van het diencephalon.</p>","image_url":"","wiki_title":"Diencephalon","match":"diencephalon|tussenhersenen","option_only":true},"ruggenmerg":{"title":"Ruggenmerg","short":"Het ruggenmerg verbindt de hersenen met de rest van het lichaam; het bevat banen in de witte stof en neuronen voor reflexen in de grijze stof.","definition":"<p>Het <strong>ruggenmerg</strong> (medulla spinalis) loopt in het wervelkanaal van het foramen magnum tot ongeveer L1–L2 (conus medullaris), waarna de cauda equina volgt. Het geeft 31 paar spinale zenuwen af.</p><p>In dwarsdoorsnede ligt de vlindervormige <em>grijze stof</em> (voorhoorn: motorneuronen; achterhoorn: sensorische schakeling) binnenin, omgeven door <em>witte stof</em> met opstijgende (bijv. achterstrengen, tractus spinothalamicus) en afdalende banen (tractus corticospinalis).</p>","image_url":"","wiki_title":"Spinal cord","match":"ruggenmerg|medulla spinalis","option_only":true},"spinale ganglia":{"title":"Spinale ganglia","short":"Spinale ganglia liggen in de achterwortels van de spinale zenuwen en bevatten de cellichamen van de sensorische (pseudo-unipolaire) neuronen.","definition":"<p>Een <strong>spinaal ganglion</strong> (dorsaalwortelganglion) is een verdikking van de achterwortel, vlak bij het foramen intervertebrale.</p><p>Het bevat de cellichamen van de <em>primaire sensorische neuronen</em>. Deze zijn pseudo-unipolair: één uitloper splitst in een perifere tak naar de receptor en een centrale tak naar het ruggenmerg. Er liggen geen synapsen in het ganglion. Het varicella-zostervirus kan hier latent blijven.</p>","image_url":"","wiki_title":"Dorsal root ganglion","match":"spinale ganglia|spinaal ganglion|ganglion spinale|dorsale wortelganglia|ganglia spinalia","option_only":true},"n. oculomotorius":{"title":"N. oculomotorius (III)","short":"De n. oculomotorius (III) innerveert de meeste uitwendige oogspieren, de ooglidheffer en (parasympathisch) de pupilvernauwer en accommodatie.","definition":"<p>De <strong>n. oculomotorius</strong> komt uit het mesencephalon en innerveert de m. rectus superior, inferior en medialis, de m. obliquus inferior en de m. levator palpebrae superioris.</p><p>Parasympathische vezels (uit de kern van Edinger-Westphal, schakeling in het ganglion ciliare) innerveren de m. sphincter pupillae (miosis) en de m. ciliaris (accommodatie). Uitval geeft een oog dat naar buiten-onder staat, ptosis en een wijde, lichtstijve pupil.</p>","image_url":"","wiki_title":"Oculomotor nerve","match":"n. oculomotorius|nervus oculomotorius|n. iii|hersenzenuw iii","option_only":true},"n. trochlearis":{"title":"N. trochlearis (IV)","short":"De n. trochlearis (IV) innerveert alleen de m. obliquus superior; hij is de enige hersenzenuw die dorsaal uit de hersenstam treedt.","definition":"<p>De <strong>n. trochlearis</strong> is de dunste hersenzenuw en de enige die aan de <em>dorsale</em> zijde van de hersenstam uittreedt (onder de colliculi inferiores) en kruist.</p><p>Hij innerveert de <em>m. obliquus superior</em>, die het oog vooral naar beneden draait als het naar binnen kijkt, en intorsie geeft. Uitval geeft verticale dubbelbeelden, vooral bij naar beneden kijken (traplopen, lezen), met compenserende hoofdkanteling naar de gezonde kant.</p>","image_url":"","wiki_title":"Trochlear nerve","match":"n. trochlearis|nervus trochlearis|n. iv|hersenzenuw iv","option_only":true},"n. trigeminus":{"title":"N. trigeminus (V)","short":"De n. trigeminus (V) is de gevoelszenuw van het gezicht (drie takken: V1, V2, V3) en de motorische zenuw van de kauwspieren.","definition":"<p>De <strong>n. trigeminus</strong> treedt uit de pons en splitst in het ganglion trigeminale in drie takken: n. ophthalmicus (V1), n. maxillaris (V2) en n. mandibularis (V3).</p><p>Sensibel verzorgt hij het gezicht, het hoornvlies (afferent deel van de cornea-reflex), mond- en neusslijmvlies en de voorste twee derde van de tong (aanraking). De motorische vezels (alleen in V3) innerveren de kauwspieren (m. masseter, m. temporalis, mm. pterygoidei).</p>","image_url":"","wiki_title":"Trigeminal nerve","match":"n. trigeminus|nervus trigeminus|n. v|hersenzenuw v","option_only":true},"nervus glossopharyngeus":{"title":"N. glossopharyngeus (IX)","short":"De n. glossopharyngeus (IX) verzorgt smaak en gevoel van het achterste derde van de tong en de keel, en ontvangt informatie van de sinus caroticus.","definition":"<p>De <strong>n. glossopharyngeus</strong> treedt uit de medulla oblongata en verlaat de schedel via het foramen jugulare.</p><p>Functies: sensibiliteit en smaak van het achterste derde van de tong, gevoel van de farynx (afferent deel van de braakreflex) en het middenoor, en afferente informatie van de baroreceptoren in de <em>sinus caroticus</em> en chemoreceptoren in het glomus caroticum. Motorisch innerveert hij de m. stylopharyngeus en parasympathisch de glandula parotidea (via het ganglion oticum).</p>","image_url":"","wiki_title":"Glossopharyngeal nerve","match":"nervus glossopharyngeus|n. glossopharyngeus|n. ix|hersenzenuw ix","option_only":true},"arteria cerebri anterior":{"title":"A. cerebri anterior","short":"De a. cerebri anterior voorziet de mediale zijde van frontaal- en pariëtaalkwab; een infarct geeft vooral uitval van het contralaterale been.","definition":"<p>De <strong>a. cerebri anterior</strong> is een eindtak van de a. carotis interna. Beide aa. cerebri anteriores zijn verbonden via de a. communicans anterior (cirkel van Willis) en lopen over het corpus callosum naar achteren.</p><p>Zij verzorgen de mediale oppervlakte van de frontaal- en pariëtaalkwab, inclusief het deel van de motorische en sensorische cortex voor <em>been en voet</em>. Een infarct geeft daardoor vooral een contralaterale parese en gevoelsstoornis van het been, soms met gedragsveranderingen en incontinentie.</p>","image_url":"","wiki_title":"Anterior cerebral artery","match":"arteria cerebri anterior|a. cerebri anterior|aca","option_only":true},"microglia":{"title":"Microglia","short":"Microglia zijn de immuuncellen (macrofagen) van het centrale zenuwstelsel; ze ruimen dode cellen en ziekteverwekkers op.","definition":"<p><strong>Microglia</strong> zijn kleine gliacellen van <em>mesodermale</em> (myeloïde) oorsprong; ze stammen af van voorlopers uit de dooierzak die vroeg in de ontwikkeling het brein binnentrekken.</p><p>Ze zijn de residente macrofagen van het CZS: ze patrouilleren, fagocyteren celresten en ziekteverwekkers, presenteren antigenen en maken cytokines. Ze spelen ook een rol bij het snoeien van synapsen in de ontwikkeling en bij neurodegeneratieve ziekten.</p>","image_url":"","wiki_title":"Microglia","match":"microglia|microgliacellen|microgliacel","option_only":true},"ependymcellen":{"title":"Ependymcellen","short":"Ependymcellen zijn gliacellen die de ventrikels en het centrale kanaal bekleden; ze helpen de liquorstroom en vormen samen met de plexus choroideus liquor.","definition":"<p><strong>Ependymcellen</strong> vormen een kubisch tot cilindrisch epitheelachtig laagje dat de ventrikels van het brein en de canalis centralis van het ruggenmerg bekleedt. Veel van hen dragen cilia en microvilli.</p><p>De cilia helpen de liquor te laten stromen. In de plexus choroideus zijn gespecialiseerde ependymcellen met tight junctions verantwoordelijk voor de productie van liquor (bloed-liquorbarrière).</p>","image_url":"","wiki_title":"Ependyma","match":"ependymcellen|ependym|ependymcel","option_only":true},"astigmatisme":{"title":"Astigmatisme","short":"Bij astigmatisme is het hoornvlies (of de lens) ongelijk gekromd, waardoor licht niet in één punt wordt gefocust en alles wat wazig of vervormd is.","definition":"<p>Bij <strong>astigmatisme</strong> is de breking van het oog niet in alle richtingen gelijk, meestal omdat het hoornvlies meer de vorm van een rugbybal dan van een voetbal heeft.</p><p>Lichtstralen in verschillende vlakken worden op verschillende afstanden gefocust, zodat er op het netvlies geen scherp punt ontstaat: zowel dichtbij als veraf is het beeld wazig of vervormd. Correctie met een <em>cilinderglas</em> (bril of torische lens).</p>","image_url":"","wiki_title":"Astigmatism","match":"astigmatisme|cilindrische afwijking","option_only":true},"ablatio retinae":{"title":"Ablatio retinae","short":"Bij een ablatio retinae laat het netvlies los van de onderliggende pigmentlaag; klachten zijn lichtflitsen, mouches volantes en een gordijn voor het oog.","definition":"<p>Bij een <strong>ablatio retinae</strong> (netvliesloslating) raakt de neurosensorische retina los van het retinale pigmentepitheel. Meestal begint het met een scheurtje in het netvlies, waardoor vocht uit het glasvocht onder het netvlies loopt (rhegmatogeen); risicofactoren zijn myopie, leeftijd en eerdere oogoperaties.</p><p>Klachten: lichtflitsen, plotseling veel ‘vliegjes’ (mouches volantes) en een zich uitbreidende schaduw of gordijn in het gezichtsveld, zonder pijn. Het is een spoedgeval: chirurgisch herstel voordat de macula loslaat.</p>","image_url":"","wiki_title":"Retinal detachment","match":"ablatio retinae|netvliesloslating|amotio retinae","option_only":true},"tia":{"title":"Transient ischaemic attack (TIA)","short":"Een TIA is een kortdurende uitval van een hersenfunctie door tijdelijke ischemie, zonder blijvend infarct; een belangrijk waarschuwingssignaal voor een herseninfarct.","definition":"<p>Bij een <strong>TIA</strong> (transient ischaemic attack) ontstaan plotseling focale neurologische klachten (bijv. halfzijdige verlamming, afasie, monoculaire blindheid) die meestal binnen enkele minuten tot een uur volledig verdwijnen, zonder infarct op beeldvorming.</p><p>De oorzaak is meestal een embolie (vanuit de carotis of het hart, bijv. bij boezemfibrilleren) of een kleine-vatenafwijking. Na een TIA is het risico op een herseninfarct in de eerste dagen sterk verhoogd; snelle analyse en secundaire preventie (antistolling of plaatjesremmers, statine, bloeddruk) zijn nodig.</p>","image_url":"","wiki_title":"Transient ischemic attack","match":"tia|transient ischaemic attack|transient ischemic attack","option_only":true},"sinus sagittalis superior":{"title":"Sinus sagittalis superior","short":"De sinus sagittalis superior is de durale sinus in de bovenrand van de falx cerebri, waarin veel corticale venen en de liquor uitmonden.","definition":"<p>De <strong>sinus sagittalis superior</strong> loopt in de middellijn van voor naar achter langs de bovenrand van de falx cerebri naar de confluens sinuum. Er monden overbruggende venen in uit, en via de arachnoïdale granulaties wordt hier liquor naar het veneuze bloed afgevoerd. Trombose ervan (sinustrombose) geeft hoofdpijn en tekenen van verhoogde druk.</p>","image_url":"","wiki_title":"Superior sagittal sinus","match":"sinus sagittalis superior","option_only":true},"sinus transversus":{"title":"Sinus transversus","short":"De sinus transversus is een durale sinus die van de confluens sinuum zijwaarts langs de aanhechting van het tentorium loopt.","definition":"<p>De <strong>sinus transversus</strong> loopt aan weerszijden horizontaal in de achterrand van het tentorium cerebelli. Hij ontvangt bloed uit de confluens sinuum (vaak rechts vooral uit de sinus sagittalis superior) en gaat over in de sinus sigmoideus. Asymmetrie tussen links en rechts is normaal.</p>","image_url":"","wiki_title":"Transverse sinuses","match":"sinus transversus","option_only":true},"sinus sigmoideus":{"title":"Sinus sigmoideus","short":"De sinus sigmoideus is de S-vormige voortzetting van de sinus transversus die via het foramen jugulare overgaat in de v. jugularis interna.","definition":"<p>De <strong>sinus sigmoideus</strong> loopt in een S-vormige groeve aan de binnenkant van het os temporale, vlak achter het mastoïd. Hij mondt uit in de bulbus van de v. jugularis interna. Door de nabijheid van het middenoor en mastoïd kan een mastoïditis uitbreiden tot een sinus sigmoideus-trombose.</p>","image_url":"","wiki_title":"Sigmoid sinus","match":"sinus sigmoideus","option_only":true},"sinus cavernosus":{"title":"Sinus cavernosus","short":"De sinus cavernosus ligt aan weerszijden van de sella turcica; erdoorheen lopen de a. carotis interna en verschillende hersenzenuwen.","definition":"<p>De <strong>sinus cavernosus</strong> is een netwerk van veneuze ruimtes naast het corpus van het os sphenoidale. Door de sinus lopen de a. carotis interna en de n. abducens (VI); in de laterale wand lopen de n. oculomotorius (III), n. trochlearis (IV) en de takken V1 en V2 van de n. trigeminus. Infecties uit het gezicht kunnen via de v. ophthalmica een sinus cavernosus-trombose veroorzaken.</p>","image_url":"","wiki_title":"Cavernous sinus","match":"sinus cavernosus","option_only":true},"n. abducens":{"title":"N. abducens (VI)","short":"De n. abducens (VI) innerveert de m. rectus lateralis, die het oog naar buiten beweegt.","definition":"<p>De <strong>n. abducens</strong> ontspringt aan de grens van pons en medulla en heeft een lang intracraniëel verloop, door de sinus cavernosus naar de orbita. Daardoor is hij gevoelig voor verhoogde intracraniële druk. Uitval geeft horizontale dubbelbeelden en een oog dat niet goed naar buiten kan bewegen.</p>","image_url":"","wiki_title":"Abducens nerve","match":"n. abducens|nervus abducens|hersenzenuw vi|n. vi","option_only":true},"nervus vagus":{"title":"N. vagus (X)","short":"De n. vagus (X) is de belangrijkste parasympathische zenuw; hij innerveert hart, longen en het maag-darmkanaal tot het distale colon transversum.","definition":"<p>De <strong>n. vagus</strong> verlaat de schedel via het foramen jugulare en loopt in de halsvaatschede omlaag. Hij levert parasympathische vezels aan hart (vertraging), luchtwegen en darm, motorische vezels aan farynx en larynx (o.a. via de n. laryngeus recurrens) en sensibele informatie uit de inwendige organen, zoals van baroreceptoren in de aortaboog.</p>","image_url":"","wiki_title":"Vagus nerve","match":"nervus vagus|n. vagus|vagus|hersenzenuw x","option_only":true},"n. facialis":{"title":"N. facialis (VII)","short":"De n. facialis (VII) innerveert de mimische spieren en verzorgt ook smaak (voorste 2/3 tong), traan- en speekselsecretie.","definition":"<p>De <strong>n. facialis</strong> treedt uit bij de brughoek, loopt door het os temporale (canalis facialis) en verlaat de schedel via het foramen stylomastoideum; daarna splitst hij zich in de glandula parotidea in vijf takken. Naast de mimische spieren innerveert hij de m. stapedius. Bij een perifere facialisparese is de hele gezichtshelft verlamd, inclusief het voorhoofd.</p>","image_url":"","wiki_title":"Facial nerve","match":"n. facialis|nervus facialis|hersenzenuw vii|aangezichtszenuw","option_only":true},"n. accessorius":{"title":"N. accessorius (XI)","short":"De n. accessorius (XI) innerveert de m. sternocleidomastoideus en m. trapezius.","definition":"<p>De spinale wortels van de <strong>n. accessorius</strong> komen uit het bovenste halsmerg, gaan omhoog door het foramen magnum en verlaten de schedel via het foramen jugulare. In de laterale halsdriehoek loopt de zenuw oppervlakkig, waar hij kwetsbaar is bij lymfeklierbiopten. Uitval geeft zwakte bij het optrekken van de schouder en het draaien van het hoofd.</p>","image_url":"","wiki_title":"Accessory nerve","match":"n. accessorius|nervus accessorius|hersenzenuw xi","option_only":true},"n. hypoglossus":{"title":"N. hypoglossus (XII)","short":"De n. hypoglossus (XII) innerveert de tongspieren.","definition":"<p>De <strong>n. hypoglossus</strong> komt uit de medulla oblongata, verlaat de schedel via het canalis hypoglossi en loopt onder de mandibula naar de tong. Hij innerveert alle intrinsieke en de meeste extrinsieke tongspieren. Bij uitval wijkt de uitgestoken tong af naar de aangedane kant, met atrofie en fasciculaties bij een perifere laesie.</p>","image_url":"","wiki_title":"Hypoglossal nerve","match":"n. hypoglossus|nervus hypoglossus|hersenzenuw xii","option_only":true},"n. infraorbitalis":{"title":"N. infraorbitalis","short":"De n. infraorbitalis is een tak van de n. maxillaris (V2) die de huid van wang, onderooglid, zijkant neus en bovenlip verzorgt.","definition":"<p>De <strong>n. infraorbitalis</strong> loopt over de orbitabodem door de canalis infraorbitalis en komt via het foramen infraorbitale op het gezicht. Bij een orbitabodemfractuur (blow-out) kan de zenuw beschadigd raken, met gevoelloosheid van wang en bovenlip als gevolg.</p>","image_url":"","wiki_title":"Infraorbital nerve","match":"n. infraorbitalis|nervus infraorbitalis","option_only":true},"perifere zenuwen":{"title":"Perifere zenuwen","short":"Perifere zenuwen verbinden het centrale zenuwstelsel met spieren, huid en organen; ze bestaan uit bundels axonen omgeven door bindweefsel.","definition":"<p>Een <strong>perifere zenuw</strong> bevat motorische, sensibele en autonome axonen, al dan niet gemyeliniseerd door Schwann-cellen. Elk axon is omgeven door endoneurium, bundels door perineurium en de hele zenuw door epineurium. Anders dan in het CZS kunnen perifere axonen na beschadiging uitgroeien (ongeveer 1 mm per dag) als de zenuwschede intact is.</p>","image_url":"","wiki_title":"Nerve","match":"perifere zenuwen|perifere zenuw","option_only":true},"motorneuronen":{"title":"Motorneuronen","short":"Motorneuronen sturen skeletspieren aan; het bovenste motorneuron loopt van cortex naar ruggenmerg, het onderste van ruggenmerg naar spier.","definition":"<p>Het <strong>bovenste motorneuron</strong> ligt in de motorische cortex en projecteert via de piramidebaan naar hersenstam en ruggenmerg; uitval geeft spasticiteit, hyperreflexie en een Babinski-reflex. Het <strong>onderste motorneuron</strong> ligt in de voorhoorn van het ruggenmerg of in hersenzenuwkernen en innerveert de spiervezels; uitval geeft slappe verlamming, atrofie, fasciculaties en hyporeflexie.</p>","image_url":"","wiki_title":"Motor neuron","match":"motorneuronen|motor neuron|motorneuron|motorische neuronen","option_only":true},"derde ventrikel":{"title":"Derde ventrikel","short":"De derde ventrikel is een smalle liquorholte in de middellijn, tussen beide thalami.","definition":"<p>De <strong>derde ventrikel</strong> ligt in het diencephalon. Ze ontvangt liquor uit de laterale ventrikels via de foramina van Monro en staat via de aquaductus cerebri in verbinding met de vierde ventrikel. In de wanden liggen de thalamus en hypothalamus; het dak bevat plexus choroideus.</p>","image_url":"","wiki_title":"Third ventricle","match":"derde ventrikel|ventriculus tertius","option_only":true},"vierde ventrikel":{"title":"Vierde ventrikel","short":"De vierde ventrikel is de liquorholte tussen hersenstam en cerebellum, met openingen naar de subarachnoïdale ruimte.","definition":"<p>De <strong>vierde ventrikel</strong> ligt achter pons en medulla oblongata en vóór het cerebellum; de bodem heet de fossa rhomboidea. Via het mediane foramen van Magendie en de laterale foramina van Luschka stroomt liquor naar de subarachnoïdale ruimte (o.a. de cisterna magna). Naar caudaal loopt hij over in de canalis centralis.</p>","image_url":"","wiki_title":"Fourth ventricle","match":"vierde ventrikel|ventriculus quartus","option_only":true},"plexus choreoïdus":{"title":"Plexus choroideus","short":"De plexus choroideus is het vaatrijke weefsel in de ventrikels dat liquor produceert.","definition":"<p>De <strong>plexus choroideus</strong> bestaat uit kluwens capillairen bedekt met gespecialiseerd ependym. De epitheelcellen zijn verbonden door tight junctions en vormen zo de bloed-liquorbarrière. Per dag wordt ongeveer 500 ml liquor gemaakt. De plexus ligt in de laterale ventrikels, het dak van de derde en vierde ventrikel.</p>","image_url":"","wiki_title":"Choroid plexus","match":"plexus choreoïdus|plexus choroideus|plexus chorioideus","option_only":true},"cisterna magna":{"title":"Cisterna magna","short":"De cisterna magna is de grootste verwijding van de subarachnoïdale ruimte, tussen cerebellum en medulla oblongata.","definition":"<p>De <strong>cisterna magna</strong> (cisterna cerebellomedullaris) ontvangt liquor uit de vierde ventrikel via het foramen van Magendie. Vroeger werd hier soms een suboccipitale punctie gedaan om liquor af te nemen. Een vergrote cisterna magna komt voor bij sommige achterste-schedelgroefafwijkingen.</p>","image_url":"","wiki_title":"Cisterna magna","match":"cisterna magna|cisterna cerebellomedullaris","option_only":true},"cerebellum":{"title":"Cerebellum (kleine hersenen)","short":"Het cerebellum coördineert beweging, evenwicht en houding en speelt een rol bij motorisch leren.","definition":"<p>Het <strong>cerebellum</strong> ligt in de achterste schedelgroeve achter de hersenstam, verbonden via drie paar pedunculi. Het vergelijkt bedoelde met uitgevoerde bewegingen en stuurt bij. Uitval geeft ataxie, intentietremor, dysmetrie, dysdiadochokinese, nystagmus en dysartrie aan dezelfde kant als de laesie.</p>","image_url":"","wiki_title":"Cerebellum","match":"cerebellum|kleine hersenen","option_only":true},"cerebrum":{"title":"Cerebrum (grote hersenen)","short":"Het cerebrum bestaat uit de twee hersenhelften met cortex, witte stof en basale kernen.","definition":"<p>Het <strong>cerebrum</strong> ontstaat uit het telencephalon. Elke hemisfeer heeft een frontale, pariëtale, temporale en occipitale kwab en de insula. De hemisferen zijn verbonden door het corpus callosum. De cortex verzorgt o.a. waarneming, motoriek, taal, geheugen en uitvoerende functies.</p>","image_url":"","wiki_title":"Cerebrum","match":"cerebrum|grote hersenen","option_only":true},"cortex cerebri":{"title":"Cortex cerebri (hersenschors)","short":"De cortex cerebri is de buitenste laag grijze stof van de grote hersenen, sterk geplooid in gyri en sulci.","definition":"<p>De <strong>cortex cerebri</strong> is 2–4 mm dik en grotendeels opgebouwd uit zes lagen (neocortex). Er worden primaire gebieden (bijv. motorische en somatosensorische cortex), unimodale associatiegebieden en multimodale associatiegebieden onderscheiden. De indeling in Brodmann-gebieden is gebaseerd op verschillen in celopbouw.</p>","image_url":"","wiki_title":"Cerebral cortex","match":"cortex cerebri|hersenschors|cerebrale cortex","option_only":true},"commisura hippocampi":{"title":"Commissura fornicis (hippocampi)","short":"De commissura hippocampi verbindt de fornices van beide kanten en daarmee de linker en rechter hippocampus.","definition":"<p>De <strong>commissura hippocampi</strong> (commissura fornicis) ligt onder het splenium van het corpus callosum, tussen de twee crura van de fornix. Via deze vezels wisselen beide hippocampi informatie uit.</p>","image_url":"","wiki_title":"Commissure of fornix","match":"commisura hippocampi|commissura hippocampi|commissura fornicis","option_only":true},"hippocampus":{"title":"Hippocampus","short":"De hippocampus ligt in de mediale temporaalkwab en is essentieel voor het vastleggen van nieuwe herinneringen.","definition":"<p>De <strong>hippocampus</strong> is onderdeel van het limbisch systeem en ligt in de bodem van de onderhoorn van de laterale ventrikel. Hij is nodig om nieuwe episodische en ruimtelijke herinneringen op te slaan (consolidatie). De belangrijkste uitgang is de fornix. Hij is gevoelig voor hypoxie en wordt vroeg aangetast bij de ziekte van Alzheimer.</p>","image_url":"","wiki_title":"Hippocampus","match":"hippocampus","option_only":true},"nucleus caudatus":{"title":"Nucleus caudatus","short":"De nucleus caudatus is een C-vormige kern van de basale ganglia langs de laterale ventrikel; samen met het putamen vormt hij het striatum.","definition":"<p>De <strong>nucleus caudatus</strong> heeft een kop (caput) in de wand van de voorhoorn van de laterale ventrikel, een lichaam en een staart die meebuigt in de temporaalkwab. Hij ontvangt vooral input uit de prefrontale en associatiecortex en speelt een rol bij cognitieve en motivationele lussen. Bij de ziekte van Huntington atrofieert de kop van de caudatus.</p>","image_url":"","wiki_title":"Caudate nucleus","match":"nucleus caudatus|caudatus","option_only":true},"nucleus anterior van de thalamus":{"title":"Nucleus anterior thalami","short":"De nucleus anterior van de thalamus maakt deel uit van het circuit van Papez en is betrokken bij geheugen en emotie.","definition":"<p>De <strong>nucleus anterior thalami</strong> ontvangt input uit de corpora mamillaria via de tractus mamillothalamicus en projecteert naar de gyrus cinguli. Zo vormt hij een schakel in het circuit van Papez (hippocampus → fornix → corpora mamillaria → nucleus anterior → gyrus cinguli → hippocampus).</p>","image_url":"","wiki_title":"Anterior nuclei of thalamus","match":"nucleus anterior van de thalamus|nucleus anterior thalami|nuclei anteriores thalami","option_only":true},"bulbus olfactorius":{"title":"Bulbus olfactorius","short":"De bulbus olfactorius is de eerste schakelplaats van de reukbaan, gelegen boven de lamina cribrosa.","definition":"<p>In de <strong>bulbus olfactorius</strong> komen de axonen van de reukreceptoren (n. olfactorius) door de lamina cribrosa binnen en schakelen in glomeruli om op mitraalcellen. Via de tractus olfactorius gaat de informatie rechtstreeks naar de reukcortex, zonder schakeling in de thalamus. Een fractuur van de lamina cribrosa kan reukverlies (anosmie) geven.</p>","image_url":"","wiki_title":"Olfactory bulb","match":"bulbus olfactorius|reukkolf","option_only":true},"tractus opticus":{"title":"Tractus opticus","short":"De tractus opticus loopt van het chiasma opticum naar het corpus geniculatum laterale en bevat vezels van beide ogen voor de tegenovergestelde gezichtshelft.","definition":"<p>Na de kruising in het chiasma bevat elke <strong>tractus opticus</strong> de vezels van het temporale netvlies van hetzelfde oog en het nasale netvlies van het andere oog. Een laesie geeft daarom een homonieme hemianopsie aan de tegenovergestelde kant. Een klein deel van de vezels gaat naar de pretectale kernen voor de pupilreflex.</p>","image_url":"","wiki_title":"Optic tract","match":"tractus opticus","option_only":true},"a. cerebri media":{"title":"A. cerebri media","short":"De a. cerebri media is de grootste eindtak van de a. carotis interna en voorziet de laterale zijde van de hemisfeer.","definition":"<p>De <strong>a. cerebri media</strong> loopt door de fissura lateralis (Sylvii) en voorziet het grootste deel van de laterale hemisfeer, inclusief de motorische en sensorische cortex voor gezicht en arm en (in de dominante hemisfeer) de taalgebieden. Lenticulostriatale takjes voorzien de basale kernen en de capsula interna. Een infarct geeft o.a. contralaterale uitval van gezicht en arm en afasie of neglect.</p>","image_url":"","wiki_title":"Middle cerebral artery","match":"a. cerebri media|arteria cerebri media|acm|mca","option_only":true},"a. cerebri posterior":{"title":"A. cerebri posterior","short":"De a. cerebri posterior ontstaat uit de a. basilaris en voorziet de occipitaalkwab, de onderkant van de temporaalkwab en de thalamus.","definition":"<p>De <strong>a. cerebri posterior</strong> ontstaat uit de splitsing van de a. basilaris en is via de a. communicans posterior verbonden met de carotiscirculatie. Ze voorziet de occipitaalkwab (visuele cortex), de mediale onderkant van de temporaalkwab en via perforerende takjes de thalamus en het mesencephalon. Een infarct geeft typisch een contralaterale homonieme hemianopsie.</p>","image_url":"","wiki_title":"Posterior cerebral artery","match":"a. cerebri posterior|arteria cerebri posterior|acp|pca","option_only":true},"arteria communicans anterior":{"title":"A. communicans anterior","short":"De a. communicans anterior verbindt de linker en rechter a. cerebri anterior in de cirkel van Willis.","definition":"<p>De <strong>a. communicans anterior</strong> is een kort vat dat de beide aa. cerebri anteriores verbindt aan de voorzijde van de cirkel van Willis. Het is een veelvoorkomende plaats voor sacculaire (bes)aneurysmata, die bij ruptuur een subarachnoïdale bloeding geven.</p>","image_url":"","wiki_title":"Anterior communicating artery","match":"arteria communicans anterior|a. communicans anterior","option_only":true},"arteria cerebelli superior":{"title":"A. cerebelli superior","short":"De a. cerebelli superior is een tak van de a. basilaris die de bovenkant van het cerebellum en delen van de hersenstam voorziet.","definition":"<p>De <strong>a. cerebelli superior</strong> ontspringt vlak onder de splitsing van de a. basilaris. Tussen deze arterie en de a. cerebri posterior loopt de n. oculomotorius. Ze voorziet de bovenzijde van het cerebellum, de cerebellaire kernen en delen van pons en mesencephalon.</p>","image_url":"","wiki_title":"Superior cerebellar artery","match":"arteria cerebelli superior|a. cerebelli superior","option_only":true},"a. meningea media":{"title":"A. meningea media","short":"De a. meningea media voorziet de dura mater; ze loopt aan de binnenkant van de schedel onder het pterion.","definition":"<p>De <strong>a. meningea media</strong> is een tak van de a. maxillaris en komt de schedel binnen via het foramen spinosum. Ze loopt tussen dura en schedelbot en heeft een voorste tak die onder het dunne pterion ligt. Een schedelfractuur op die plek kan de arterie scheuren, met een epiduraal hematoom als gevolg.</p>","image_url":"","wiki_title":"Middle meningeal artery","match":"a. meningea media|arteria meningea media","option_only":true},"episodisch geheugen":{"title":"Episodisch geheugen","short":"Het episodisch geheugen bevat persoonlijke gebeurtenissen met hun tijd en plaats.","definition":"<p>Het <strong>episodisch geheugen</strong> is een onderdeel van het declaratieve (expliciete) langetermijngeheugen. Het slaat specifieke, persoonlijk beleefde gebeurtenissen op, zoals wat je gisteren hebt gegeten. Het is sterk afhankelijk van de hippocampus en de mediale temporaalkwab en wordt vroeg aangetast bij de ziekte van Alzheimer.</p>","image_url":"","wiki_title":"Episodic memory","match":"episodisch geheugen","option_only":true},"semantisch geheugen":{"title":"Semantisch geheugen","short":"Het semantisch geheugen bevat algemene feitenkennis en betekenissen, los van wanneer je ze leerde.","definition":"<p>Het <strong>semantisch geheugen</strong> is het deel van het declaratieve geheugen waarin kennis over de wereld ligt opgeslagen, zoals woordbetekenissen en feiten (Parijs is de hoofdstad van Frankrijk). Het is vooral verbonden met de (voorste) temporaalkwab en is selectief aangedaan bij semantische dementie.</p>","image_url":"","wiki_title":"Semantic memory","match":"semantisch geheugen","option_only":true},"werkgeheugen":{"title":"Werkgeheugen","short":"Het werkgeheugen houdt informatie kort actief vast en bewerkt die, bijvoorbeeld bij hoofdrekenen.","definition":"<p>Het <strong>werkgeheugen</strong> heeft een beperkte capaciteit (een paar items) en houdt informatie seconden vast terwijl je ermee bezig bent. Volgens het model van Baddeley bestaat het uit een centrale uitvoerder, een fonologische lus en een visueel-ruimtelijk schetsblok. Het is sterk afhankelijk van de prefrontale cortex.</p>","image_url":"","wiki_title":"Working memory","match":"werkgeheugen|kortetermijngeheugen","option_only":true},"astrocyt":{"title":"Astrocyt","short":"Astrocyten zijn stervormige gliacellen in het CZS die neuronen ondersteunen, ionen en neurotransmitters regelen en de bloed-hersenbarrière helpen vormen.","definition":"<p><strong>Astrocyten</strong> zijn de talrijkste gliacellen. Met hun uitlopers (eindvoetjes) omhullen ze capillairen en induceren ze de tight junctions van de bloed-hersenbarrière. Ze nemen kalium en glutamaat op, slaan glycogeen op en vormen na schade een glialitteken (gliose). Ze brengen GFAP tot expressie; tumoren ervan heten astrocytomen.</p>","image_url":"","wiki_title":"Astrocyte","match":"astrocyt|astrocyten","option_only":true},"satellietcel":{"title":"Satellietcel","short":"De term satellietcel wordt gebruikt voor de stamcellen van skeletspier en voor de steuncellen rond neuronen in perifere ganglia.","definition":"<p>In <strong>skeletspier</strong> liggen satellietcellen tussen de basale lamina en het sarcolemma van de spiervezel. Het zijn spierstamcellen die bij schade delen en fuseren met bestaande vezels voor herstel en groei. In <strong>perifere ganglia</strong> (spinale en autonome ganglia) zijn satellietcellen gliacellen die de cellichamen van neuronen omringen en ondersteunen.</p>","image_url":"","wiki_title":"Myosatellite cell","match":"satellietcel|satellietcellen","option_only":true},"neuritis vestibularis":{"title":"Neuritis vestibularis","short":"Neuritis vestibularis is een (vermoedelijk virale) ontsteking van de n. vestibularis met acute, dagenlange draaiduizeligheid zonder gehoorverlies.","definition":"<p>Bij <strong>neuritis vestibularis</strong> valt het evenwichtsorgaan aan één kant plotseling uit. Dat geeft heftige draaiduizeligheid, misselijkheid, braken en een horizontale nystagmus naar de gezonde kant, zonder gehoorverlies of andere neurologische uitval. De head-impulstest is afwijkend. Het herstel verloopt over dagen tot weken via centrale compensatie.</p>","image_url":"","wiki_title":"Vestibular neuritis","match":"neuritis vestibularis|neuronitis vestibularis","option_only":true},"cva":{"title":"CVA (beroerte)","short":"Een CVA (beroerte) is plotselinge neurologische uitval door een herseninfarct of hersenbloeding.","definition":"<p>Een <strong>cerebrovasculair accident</strong> is in ongeveer 80% van de gevallen een herseninfarct en in de rest een hersenbloeding (intracerebraal of subarachnoïdaal). Beeldvorming (CT) is nodig om bloeding en infarct te onderscheiden, omdat de behandeling sterk verschilt. Belangrijke risicofactoren zijn hypertensie, roken, diabetes, hypercholesterolemie en boezemfibrilleren.</p>","image_url":"","wiki_title":"Stroke","match":"cva|beroerte|cerebrovasculair accident|stroke","option_only":true},"paroxysmaal atriumfibrilleren":{"title":"Paroxysmaal atriumfibrilleren","short":"Bij paroxysmaal atriumfibrilleren treden aanvallen van boezemfibrilleren op die binnen 7 dagen vanzelf stoppen.","definition":"<p>Bij <strong>atriumfibrilleren</strong> is de elektrische activiteit van de boezems chaotisch; de kamers slaan onregelmatig en vaak snel. In de paroxysmale vorm duren episodes korter dan een week en eindigen ze spontaan. Er is een verhoogd risico op trombo-embolie (vooral herseninfarct) vanuit het linkerhartoor; afhankelijk van de CHA₂DS₂-VASc-score wordt antistolling gegeven.</p>","image_url":"","wiki_title":"Atrial fibrillation","match":"paroxysmaal atriumfibrilleren|paroxysmaal boezemfibrilleren|atriumfibrilleren|boezemfibrilleren","option_only":true},"aortaklepstenose":{"title":"Aortaklepstenose","short":"Bij aortaklepstenose opent de aortaklep onvoldoende, waardoor de linkerventrikel tegen verhoogde weerstand moet pompen.","definition":"<p><strong>Aortaklepstenose</strong> ontstaat meestal door degeneratieve verkalking op oudere leeftijd of bij een aangeboren bicuspide klep. De linkerventrikel hypertrofieert. Bij auscultatie is er een systolisch ejectiegeruis aan de basis, vaak uitstralend naar de carotiden. Klachten (angina, syncope bij inspanning, hartfalen) wijzen op een ernstige stenose; behandeling is klepvervanging (chirurgisch of TAVI).</p>","image_url":"","wiki_title":"Aortic stenosis","match":"aortaklepstenose|aortastenose","option_only":true},"orthostatische hypotensie":{"title":"Orthostatische hypotensie","short":"Orthostatische hypotensie is een bloeddrukdaling bij het opstaan door onvoldoende compensatie van het autonome zenuwstelsel.","definition":"<p>Bij <strong>orthostatische hypotensie</strong> daalt de systolische bloeddruk met ≥20 mmHg (of de diastolische met ≥10 mmHg) binnen 3 minuten na overeind komen. Normaal zorgt de baroreflex voor vasoconstrictie en een hogere hartfrequentie. Oorzaken zijn o.a. ondervulling, medicatie (antihypertensiva, diuretica, antidepressiva) en autonome neuropathie. Klachten: duizeligheid, wazig zien en wegraking bij opstaan.</p>","image_url":"","wiki_title":"Orthostatic hypotension","match":"orthostatische hypotensie","option_only":true},"osteoporose":{"title":"Osteoporose","short":"Osteoporose is een verlaagde botmassa met verzwakte botstructuur, waardoor botten sneller breken.","definition":"<p>Bij <strong>osteoporose</strong> is de afbraak van bot groter dan de opbouw. Risicofactoren: hoge leeftijd, postmenopauzaal oestrogeentekort, corticosteroïden, laag lichaamsgewicht, roken, alcohol en weinig beweging. Typische fracturen zijn wervelinzakkingen, heupfracturen en distale radiusfracturen. Diagnose met een DEXA-scan (T-score ≤ −2,5); behandeling o.a. met bisfosfonaten, calcium en vitamine D.</p>","image_url":"","wiki_title":"Osteoporosis","match":"osteoporose|botontkalking","option_only":true},"fotopsie":{"title":"Fotopsie","short":"Fotopsieën zijn lichtflitsen zonder dat er licht is, vaak door mechanische prikkeling van het netvlies.","definition":"<p><strong>Fotopsieën</strong> ontstaan vaak wanneer het glasvocht aan het netvlies trekt, bijvoorbeeld bij een achterste glasvochtloslating; ze worden dan vooral in het donker en bij oogbewegingen gezien. Plots nieuwe lichtflitsen met veel ‘vliegjes’ of een schaduw vereisen onderzoek naar een netvliesscheur of -loslating. Ook een migraine-aura kan lichtverschijnselen geven.</p>","image_url":"","wiki_title":"Photopsia","match":"fotopsie|lichtflitsen","option_only":true},"chromatopsie":{"title":"Chromatopsie","short":"Chromatopsie is het zien in een bepaalde kleurtint, bijvoorbeeld alles geel of groen.","definition":"<p>Bij <strong>chromatopsie</strong> lijkt de hele omgeving een kleurzweem te hebben. Een bekend voorbeeld is xanthopsie (geelzien) bij een digoxine-intoxicatie. Ook na een staaroperatie (meer blauw licht) en bij sommige andere geneesmiddelen kunnen kleurverschuivingen optreden.</p>","image_url":"","wiki_title":"Chromatopsia","match":"chromatopsie","option_only":true},"oscillopsie":{"title":"Oscillopsie","short":"Oscillopsie is de illusie dat de omgeving heen en weer beweegt of trilt.","definition":"<p><strong>Oscillopsie</strong> ontstaat als het beeld niet stabiel op het netvlies blijft, bijvoorbeeld bij dubbelzijdige uitval van het evenwichtsorgaan (vooral bij lopen of hoofdbewegingen) of bij verworven nystagmus. Bij aangeboren nystagmus komt het meestal niet voor, omdat het brein zich heeft aangepast.</p>","image_url":"","wiki_title":"Oscillopsia","match":"oscillopsie","option_only":true},"vagus":{"title":"N. vagus (X)","short":"De n. vagus (X) is de belangrijkste parasympathische zenuw; hij innerveert hart, longen en het maag-darmkanaal.","definition":"<p>De <strong>n. vagus</strong> verlaat de schedel via het foramen jugulare en loopt in de halsvaatschede omlaag. Hij levert parasympathische vezels aan hart, luchtwegen en darm, motorische vezels aan farynx en larynx en sensibele informatie uit de inwendige organen.</p>","image_url":"","wiki_title":"Vagus nerve","match":"vagus","option_only":true},"atriumseptum defect":{"title":"Atriumseptumdefect (ASD)","short":"Een ASD is een aangeboren opening in het septum tussen de boezems, met een links-rechtsshunt.","definition":"<p>Bij een <strong>atriumseptumdefect</strong> (meestal type secundum) stroomt bloed van het linker- naar het rechteratrium, met volumebelasting van het rechterhart en de longcirculatie. Het geeft vaak pas op volwassen leeftijd klachten (vermoeidheid, kortademigheid, boezemfibrilleren). Kenmerkend is een vaste splijting van de tweede harttoon. Sluiting kan meestal via een katheter.</p>","image_url":"","wiki_title":"Atrial septal defect","match":"atriumseptum defect|atriumseptumdefect|asd","option_only":true},"atherosclerose":{"title":"Atherosclerose","short":"Atherosclerose is een chronisch ontstekingsproces in de vaatwand waarbij plaques met vet, ontstekingscellen en bindweefsel ontstaan.","definition":"<p>Bij <strong>atherosclerose</strong> dringt LDL de intima binnen en wordt het geoxideerd; monocyten worden macrofagen en schuimcellen (fatty streak). Gladde spiercellen migreren en vormen een fibreuze kap over een lipidenkern. Scheuren van een plaque met trombose veroorzaakt een acuut coronair syndroom of herseninfarct. Risicofactoren: roken, hypertensie, LDL, diabetes, leeftijd en familiaire belasting.</p>","image_url":"","wiki_title":"Atherosclerosis","match":"atherosclerose|aderverkalking|arteriosclerose","option_only":true},"neurogene blaas":{"title":"Neurogene blaas","short":"Bij een neurogene blaas is de blaasfunctie verstoord door een aandoening van het zenuwstelsel.","definition":"<p>Bij een <strong>neurogene blaas</strong> ontstaat afhankelijk van de plaats van de laesie een overactieve blaas (letsel boven het sacrale mictiecentrum, bijv. MS of dwarslaesie) of juist een slappe blaas met retentie en overloopincontinentie (letsel van het sacrale merg, cauda equina of perifere zenuwen, bijv. diabetes). Complicaties zijn urineweginfecties en nierschade.</p>","image_url":"","wiki_title":"Neurogenic bladder dysfunction","match":"neurogene blaas|neurogene blaasdisfunctie","option_only":true},"spastische paraparese":{"title":"Spastische paraparese","short":"Spastische paraparese is zwakte met verhoogde spierspanning van beide benen, door schade aan de piramidebanen.","definition":"<p>Bij een <strong>spastische paraparese</strong> zijn de benen zwak en stijf, met hyperreflexie en Babinski-reflexen. Oorzaken zijn o.a. een myelopathie (compressie, MS, B12-tekort), hereditaire spastische paraparese en spastische cerebrale parese (vooral bij prematuren met periventriculaire leukomalacie). Bij een acute myelopathie is snelle beeldvorming nodig.</p>","image_url":"","wiki_title":"Spastic paraplegia","match":"spastische paraparese","option_only":true},"globale ontwikkelingsachterstand":{"title":"Globale ontwikkelingsachterstand","short":"Bij een globale ontwikkelingsachterstand loopt een jong kind op twee of meer ontwikkelingsdomeinen duidelijk achter.","definition":"<p>Van een <strong>globale ontwikkelingsachterstand</strong> spreekt men bij kinderen onder de vijf jaar met een achterstand in bijvoorbeeld motoriek, taal en spraak, cognitie en sociale ontwikkeling. Oorzaken zijn o.a. genetische afwijkingen (bijv. fragiele X, microdeleties), perinatale problemen, infecties, metabole ziekten en ernstige verwaarlozing. Diagnostiek o.a. met genetisch onderzoek.</p>","image_url":"","wiki_title":"Global developmental delay","match":"globale ontwikkelingsachterstand|ontwikkelingsachterstand","option_only":true},"abducens":{"title":"N. abducens (VI)","short":"De n. abducens (VI) innerveert de m. rectus lateralis, die het oog naar buiten beweegt.","definition":"<p>De <strong>n. abducens</strong> ontspringt aan de grens van pons en medulla en heeft een lang intracraniëel verloop, door de sinus cavernosus naar de orbita. Daardoor is hij gevoelig voor verhoogde intracraniële druk. Uitval geeft horizontale dubbelbeelden en een oog dat niet goed naar buiten kan bewegen.</p>","image_url":"","wiki_title":"Abducens nerve","match":"abducens","option_only":true},"facialis":{"title":"N. facialis (VII)","short":"De n. facialis (VII) innerveert de mimische spieren en verzorgt ook smaak (voorste 2/3 tong), traan- en speekselsecretie.","definition":"<p>De <strong>n. facialis</strong> treedt uit bij de brughoek, loopt door het os temporale (canalis facialis) en verlaat de schedel via het foramen stylomastoideum; daarna splitst hij zich in de glandula parotidea in vijf takken. Naast de mimische spieren innerveert hij de m. stapedius. Bij een perifere facialisparese is de hele gezichtshelft verlamd, inclusief het voorhoofd.</p>","image_url":"","wiki_title":"Facial nerve","match":"facialis","option_only":true},"oculomotorius":{"title":"N. oculomotorius (III)","short":"De n. oculomotorius (III) innerveert de meeste uitwendige oogspieren, de ooglidheffer en (parasympathisch) de pupilvernauwer en accommodatie.","definition":"<p>De <strong>n. oculomotorius</strong> komt uit het mesencephalon en innerveert de m. rectus superior, inferior en medialis, de m. obliquus inferior en de m. levator palpebrae superioris.</p><p>Parasympathische vezels (uit de kern van Edinger-Westphal, schakeling in het ganglion ciliare) innerveren de m. sphincter pupillae (miosis) en de m. ciliaris (accommodatie). Uitval geeft een oog dat naar buiten-onder staat, ptosis en een wijde, lichtstijve pupil.</p>","image_url":"","wiki_title":"Oculomotor nerve","match":"oculomotorius","option_only":true},"optokinetische nystagmus":{"title":"Optokinetische nystagmus","short":"Optokinetische nystagmus is een normale reflexmatige oogbeweging bij het volgen van een bewegend patroon, zoals uit het raam van een rijdende trein kijken.","definition":"<p>Bij <strong>optokinetische nystagmus</strong> volgen de ogen het bewegende beeld langzaam (volgbeweging) en springen dan snel terug (saccade). Het wordt gebruikt om het zien te testen bij baby's en mensen die niet kunnen communiceren, en om simulatie van blindheid uit te sluiten.</p>","image_url":"","wiki_title":"Optokinetic response","match":"optokinetische nystagmus|okn","option_only":true},"n. vestibulocochlearis":{"title":"N. vestibulocochlearis (VIII)","short":"De n. vestibulocochlearis (VIII) voert informatie over horen en evenwicht van het binnenoor naar de hersenstam.","definition":"<p>De <strong>n. vestibulocochlearis</strong> bestaat uit een cochleair deel (horen) en een vestibulair deel (evenwicht) en treedt bij de brughoek de hersenstam binnen, via de inwendige gehoorgang samen met de n. facialis. Een vestibulair schwannoom groeit vanuit deze zenuw.</p>","image_url":"","wiki_title":"Vestibulocochlear nerve","match":"n. vestibulocochlearis|nervus vestibulocochlearis|n. viii|hersenzenuw viii","option_only":true},"gyrus precentralis":{"title":"Gyrus precentralis (primaire motorische cortex)","short":"De gyrus precentralis is de primaire motorische cortex, vlak vóór de sulcus centralis in de frontaalkwab.","definition":"<p>In de <strong>gyrus precentralis</strong> liggen de bovenste motorneuronen (waaronder de cellen van Betz) die via de piramidebaan de spieren van de andere lichaamshelft aansturen. De lichaamsdelen zijn somatotopisch geordend (motorische homunculus), met het been mediaal en gezicht en hand lateraal.</p>","image_url":"","wiki_title":"Primary motor cortex","match":"gyrus precentralis|primaire motorische cortex","option_only":true},"gyrus postcentralis":{"title":"Gyrus postcentralis (primaire sensorische cortex)","short":"De gyrus postcentralis is de primaire somatosensorische cortex, direct achter de sulcus centralis in de pariëtaalkwab.","definition":"<p>De <strong>gyrus postcentralis</strong> ontvangt via de thalamus tast-, pijn-, temperatuur- en positie-informatie van de andere lichaamshelft, somatotopisch geordend (sensorische homunculus). Een laesie geeft contralaterale gevoelsstoornissen.</p>","image_url":"","wiki_title":"Postcentral gyrus","match":"gyrus postcentralis|primaire somatosensorische cortex","option_only":true},"corpus geniculate laterale":{"title":"Corpus geniculatum laterale","short":"Het corpus geniculatum laterale is de schakelkern in de thalamus voor de visuele baan.","definition":"<p>Het <strong>CGL</strong> ontvangt vezels van de tractus opticus en projecteert via de radiatio optica naar de primaire visuele cortex in de occipitaalkwab. Het heeft zes lagen, waarbij vezels van beide ogen in aparte lagen eindigen.</p>","image_url":"","wiki_title":"Lateral geniculate nucleus","match":"corpus geniculate laterale|corpus geniculatum laterale|cgl","option_only":true},"corpus geniculate mediale":{"title":"Corpus geniculatum mediale","short":"Het corpus geniculatum mediale is de schakelkern in de thalamus voor de gehoorbaan.","definition":"<p>Het <strong>corpus geniculatum mediale</strong> ontvangt informatie van de colliculus inferior en projecteert naar de primaire auditieve cortex in de gyrus temporalis superior (gyri van Heschl).</p>","image_url":"","wiki_title":"Medial geniculate nucleus","match":"corpus geniculate mediale|corpus geniculatum mediale","option_only":true},"carotisstenose":{"title":"Carotisstenose","short":"Een carotisstenose is een vernauwing van de halsslagader (meestal de a. carotis interna) door atherosclerose, met risico op een herseninfarct.","definition":"<p>Een <strong>carotisstenose</strong> kan embolieën veroorzaken naar het oog (amaurosis fugax) of de hemisfeer (TIA of herseninfarct). Bij een symptomatische, ernstige stenose verlaagt een endarteriëctomie het risico op een nieuw infarct, mits snel uitgevoerd. Opsporing met duplexonderzoek.</p>","image_url":"","wiki_title":"Carotid artery stenosis","match":"carotisstenose|stenose arteria carotis interna rechts|stenose a. carotis interna","option_only":true},"sinus petrosus superior":{"title":"Sinus petrosus superior","short":"De sinus petrosus superior is een durale veneuze sinus langs de bovenrand van het rotsbeen, van de sinus cavernosus naar de sinus transversus/sigmoideus.","definition":"<p>De <strong>sinus petrosus superior</strong> loopt in de aanhechting van het tentorium op de bovenrand van de pars petrosa van het os temporale. Hij voert bloed af uit de sinus cavernosus.</p>","image_url":"","wiki_title":"Superior petrosal sinus","match":"sinus petrosus superior","option_only":true},"granulationes arachnoidales":{"title":"Arachnoïdale granulaties","short":"Arachnoïdale granulaties zijn uitstulpingen van de arachnoidea in de durale sinussen, waarlangs liquor naar het veneuze bloed wordt afgevoerd.","definition":"<p>Via de <strong>arachnoïdale granulaties</strong> (vooral in de sinus sagittalis superior) wordt liquor geresorbeerd. Bij een verstoorde resorptie (bijv. na een subarachnoïdale bloeding of meningitis) kan een communicerende hydrocephalus ontstaan.</p>","image_url":"","wiki_title":"Arachnoid granulation","match":"granulationes arachnoidales|arachnoïdale villi|arachnoïdale granulaties|granulaties van pacchioni","option_only":true},"glaucoom":{"title":"Glaucoom","short":"Glaucoom is een groep oogziekten met schade aan de oogzenuw en gezichtsvelduitval, meestal samenhangend met een verhoogde oogdruk.","definition":"<p>Bij het meest voorkomende <strong>openkamerhoekglaucoom</strong> verloopt de schade langzaam en ongemerkt, met eerst uitval in het perifere gezichtsveld en een toenemende excavatie van de papil. Risicofactoren: hogere leeftijd, verhoogde oogdruk, familie, myopie en een donkere huidskleur. Behandeling met oogdrukverlagende druppels, laser of operatie. Acuut glaucoom is een apart, acuut ziektebeeld.</p>","image_url":"","wiki_title":"Glaucoma","match":"glaucoom|groene staar|openkamerhoekglaucoom","option_only":true},"cerebral palsy":{"title":"Cerebrale parese","short":"Cerebrale parese is een blijvende houdings- en bewegingsstoornis door een niet-progressieve beschadiging van het zich ontwikkelende brein.","definition":"<p>Oorzaken van <strong>cerebrale parese</strong> liggen vóór, rond of kort na de geboorte: prematuriteit (periventriculaire leukomalacie), asfyxie, infecties, herseninfarcten en afwijkingen in de aanleg. Vormen zijn spastisch (meest voorkomend), dyskinetisch en ataxisch. Vaak zijn er bijkomende problemen zoals epilepsie, verstandelijke beperking en slikproblemen.</p>","image_url":"","wiki_title":"Cerebral palsy","match":"cerebral palsy|cerebrale parese|cp","option_only":true},"uveitis anterior":{"title":"Uveïtis anterior","short":"Uveïtis anterior is een ontsteking van iris en corpus ciliare, met een pijnlijk rood oog, lichtschuwheid en wazig zien.","definition":"<p>Bij <strong>uveïtis anterior</strong> zijn er cellen en flare in de voorste oogkamer, ciliaire injectie en soms een nauwe of onregelmatige pupil (synechieën). Het kan samenhangen met HLA-B27-gerelateerde ziekten, sarcoïdose, JIA of infecties. Behandeling met corticosteroïd- en pupilverwijdende druppels.</p>","image_url":"","wiki_title":"Uveitis","match":"uveitis anterior|uveïtis anterior|iridocyclitis|iritis","option_only":true},"maculopathie":{"title":"Maculopathie","short":"Maculopathie is een aandoening van de macula, het centrum van het netvlies, met verlies van het scherpe zien.","definition":"<p>Voorbeelden zijn leeftijdsgebonden maculadegeneratie, <strong>diabetisch maculaoedeem</strong> (lekkage uit beschadigde vaatjes), maculaoedeem na een veneuze occlusie of operatie, en erfelijke maculadystrofieën. Behandeling van oedeem vaak met anti-VEGF-injecties.</p>","image_url":"","wiki_title":"Macular edema","match":"maculopathie|macula oedeem|maculaoedeem|diabetisch macula oedeem","option_only":true},"insomnia":{"title":"Insomnie","short":"Insomnie is aanhoudend moeite met inslapen, doorslapen of te vroeg wakker worden, met klachten overdag.","definition":"<p>Bij <strong>chronische insomnie</strong> (minstens drie nachten per week, drie maanden) is cognitieve gedragstherapie voor insomnie de eerste keus, met o.a. slaaprestrictie en stimuluscontrole. Slaapmiddelen zijn alleen kortdurend geschikt wegens gewenning en afhankelijkheid.</p>","image_url":"","wiki_title":"Insomnia","match":"insomnia|insomnie|slapeloosheid","option_only":true},"plexus choreo&iuml;dus":{"title":"Plexus choroideus","short":"De plexus choroideus is het vaatrijke weefsel in de ventrikels dat liquor produceert.","definition":"<p>De <strong>plexus choroideus</strong> bestaat uit kluwens capillairen bedekt met gespecialiseerd ependym. De epitheelcellen zijn verbonden door tight junctions en vormen zo de bloed-liquorbarrière. Per dag wordt ongeveer 500 ml liquor gemaakt. De plexus ligt in de laterale ventrikels, het dak van de derde en vierde ventrikel.</p>","image_url":"","wiki_title":"Choroid plexus","match":"plexus choreo&iuml;dus","option_only":true},"refractie afwijking":{"title":"Refractieafwijking","short":"Een refractieafwijking betekent dat het oog licht niet scherp op het netvlies focust: bijziendheid, verziendheid of astigmatisme.","definition":"<p>Bij <strong>myopie</strong> (bijziendheid) valt het brandpunt vóór de retina, bij <strong>hypermetropie</strong> (verziendheid) erachter, en bij <strong>astigmatisme</strong> is de breking niet in alle richtingen gelijk. Presbyopie is leeftijdsgebonden verlies van accommodatie. Verbetering van het zicht met een stenopeïsche opening wijst op een refractieprobleem. Correctie met bril, lenzen of refractiechirurgie.</p>","image_url":"","wiki_title":"Refractive error","match":"refractie afwijking","option_only":true},"schwann-cellen":{"title":"Schwann-cellen","short":"Schwann-cellen zijn gliacellen van het perifere zenuwstelsel die axonen omhullen en myeliniseren.","definition":"<p>Een <strong>Schwann-cel</strong> myeliniseert één stukje van één axon (anders dan een oligodendrocyt in het CZS, die meerdere axonen bedient). Ze ondersteunen ook het herstel na zenuwschade. Tumoren ervan heten schwannomen.</p>","image_url":"","wiki_title":"Schwann cell","match":"schwann-cellen|schwanncellen|cel van schwann","option_only":true},"striatum":{"title":"Striatum","short":"Het striatum (nucleus caudatus en putamen) is het belangrijkste inputstation van de basale kernen.","definition":"<p>Het <strong>striatum</strong> ontvangt projecties uit vrijwel de hele cortex en dopaminerge input uit de substantia nigra. Via de directe en indirecte route stuurt het de output van de basale kernen. Het ventrale deel (nucleus accumbens) speelt een rol bij beloning en motivatie.</p>","image_url":"","wiki_title":"Striatum","match":"striatum|corpus striatum","option_only":true},"cel van schwann":{"title":"Schwann-cellen","short":"Schwann-cellen zijn gliacellen van het perifere zenuwstelsel die axonen omhullen en myeliniseren.","definition":"<p>Een <strong>Schwann-cel</strong> myeliniseert één stukje van één axon (anders dan een oligodendrocyt in het CZS, die meerdere axonen bedient). Ze ondersteunen ook het herstel na zenuwschade. Tumoren ervan heten schwannomen.</p>","image_url":"","wiki_title":"Schwann cell","match":"cel van schwann","option_only":true},"ventrale striatum":{"title":"Striatum","short":"Het striatum (nucleus caudatus en putamen) is het belangrijkste inputstation van de basale kernen.","definition":"<p>Het <strong>striatum</strong> ontvangt projecties uit vrijwel de hele cortex en dopaminerge input uit de substantia nigra. Via de directe en indirecte route stuurt het de output van de basale kernen. Het ventrale deel (nucleus accumbens) speelt een rol bij beloning en motivatie.</p>","image_url":"","wiki_title":"Striatum","match":"ventrale striatum","option_only":true},"hyperthermie":{"title":"Hyperthermie","short":"Bij hyperthermie stijgt de lichaamstemperatuur doordat warmteproductie of -opname groter is dan de warmteafgifte, zonder verhoogd setpoint.","definition":"<p>Anders dan bij koorts is het setpoint bij <strong>hyperthermie</strong> niet verhoogd, zodat koortsremmers niet helpen. Oorzaken: hitteberoerte, inspanning in de hitte, maligne hyperthermie (na bepaalde anesthetica), het maligne neurolepticasyndroom, serotoninesyndroom en drugs (MDMA, cocaïne). Behandeling: actief koelen.</p>","image_url":"","wiki_title":"Hyperthermia","match":"hyperthermie|oververhitting|hitteberoerte","option_only":true},"horner syndroom":{"title":"Syndroom van Horner","short":"Het syndroom van Horner is uitval van de sympathische innervatie van het oog, met ptosis, miosis en soms verminderd zweten.","definition":"<p>Bij <strong>Horner</strong> is de pupil kleiner (vooral zichtbaar in het donker), hangt het bovenooglid iets en zweet de gezichtshelft soms minder. Oorzaken liggen ergens langs de lange sympathische baan: hersenstam (bijv. infarct), ruggenmerg, longtop (Pancoast-tumor) of rond de a. carotis (dissectie, met pijn).</p>","image_url":"","wiki_title":"Horner's syndrome","match":"horner syndroom|syndroom van horner|horner","option_only":true},"lamina terminalis":{"title":"Lamina terminalis","short":"De lamina terminalis is de dunne voorwand van de derde ventrikel, het restant van de craniale sluiting van de neurale buis.","definition":"<p>In en rond de <strong>lamina terminalis</strong> liggen circumventriculaire organen (zoals het organum vasculosum), die bloed ‘proeven’ omdat daar geen bloed-hersenbarrière is, en betrokken zijn bij dorst en de koortsreactie.</p>","image_url":"","wiki_title":"Lamina terminalis","match":"lamina terminalis","option_only":true},"rotsbeen":{"title":"Rotsbeen (pars petrosa)","short":"Het rotsbeen is het harde, piramidevormige deel van het os temporale waarin middenoor en binnenoor liggen.","definition":"<p>In het <strong>rotsbeen</strong> liggen de cochlea, het evenwichtsorgaan, de gehoorbeentjes, de canalis facialis en de a. carotis interna. Een rotsbeenfractuur kan gehoorverlies, een facialisparese, liquorlekkage uit het oor en een hematotympanum geven.</p>","image_url":"","wiki_title":"Petrous part of the temporal bone","match":"rotsbeen|pars petrosa|os petrosum","option_only":true},"ovale venster":{"title":"Ovale venster","short":"Het ovale venster is de opening naar het binnenoor waarin de voetplaat van de stijgbeugel past.","definition":"<p>Trillingen van het trommelvlies worden via hamer en aambeeld naar de stijgbeugel en het <strong>ovale venster</strong> geleid, wat golven in de vloeistof van de cochlea veroorzaakt. Het ronde venster laat de druk weer ontwijken. Bij otosclerose groeit de stijgbeugel vast in het ovale venster, met een geleidingsverlies.</p>","image_url":"","wiki_title":"Oval window","match":"ovale venster|fenestra vestibuli","option_only":true},"sinus frontalis":{"title":"Sinus frontalis","short":"De sinus frontalis is de bijholte in het voorhoofdsbeen, die via de ductus frontonasalis in de neus uitmondt.","definition":"<p>De <strong>voorhoofdsholte</strong> ontwikkelt zich pas in de kindertijd. Een infectie kan uitbreiden naar de oogkas of de voorste schedelgroeve (bijv. een abces of het Pott's puffy tumor), al is dat zeldzaam.</p>","image_url":"","wiki_title":"Frontal sinus","match":"sinus frontalis|voorhoofdsholte","option_only":true},"parenchymateuze bloeding":{"title":"Intracerebrale bloeding","short":"Een intracerebrale bloeding is een bloeding in het hersenweefsel zelf, meestal door hypertensie of amyloïdangiopathie.","definition":"<p><strong>Hypertensieve bloedingen</strong> liggen vaak diep (basale kernen, thalamus, pons, cerebellum); <strong>lobaire bloedingen</strong> bij ouderen passen bij amyloïdangiopathie. Andere oorzaken: antistolling, vaatmalformaties en tumoren. Klachten ontstaan plotseling, vaak met hoofdpijn en braken. Diagnose met CT.</p>","image_url":"","wiki_title":"Intracerebral hemorrhage","match":"parenchymateuze bloeding|intracerebrale bloeding|hersenbloeding","option_only":true},"vestibulocochlearis":{"title":"N. vestibulocochlearis (VIII)","short":"De n. vestibulocochlearis (VIII) voert informatie over horen en evenwicht van het binnenoor naar de hersenstam.","definition":"<p>De <strong>n. vestibulocochlearis</strong> bestaat uit een cochleair deel (horen) en een vestibulair deel (evenwicht) en treedt bij de brughoek de hersenstam binnen, via de inwendige gehoorgang samen met de n. facialis. Een vestibulair schwannoom groeit vanuit deze zenuw.</p>","image_url":"","wiki_title":"Vestibulocochlear nerve","match":"vestibulocochlearis","option_only":true},"trigeminus":{"title":"N. trigeminus (V)","short":"De n. trigeminus (V) is de gevoelszenuw van het gezicht (drie takken: V1, V2, V3) en de motorische zenuw van de kauwspieren.","definition":"<p>De <strong>n. trigeminus</strong> treedt uit de pons en splitst in het ganglion trigeminale in drie takken: n. ophthalmicus (V1), n. maxillaris (V2) en n. mandibularis (V3).</p><p>Sensibel verzorgt hij het gezicht, het hoornvlies (afferent deel van de cornea-reflex), mond- en neusslijmvlies en de voorste twee derde van de tong (aanraking). De motorische vezels (alleen in V3) innerveren de kauwspieren (m. masseter, m. temporalis, mm. pterygoidei).</p>","image_url":"","wiki_title":"Trigeminal nerve","match":"trigeminus","option_only":true},"hydrocephalus":{"title":"Hydrocefalus","short":"Bij hydrocefalus hoopt liquor zich op in de ventrikels door een stoornis in productie, doorstroming of resorptie.","definition":"<p>Bij een <strong>obstructieve</strong> hydrocefalus is de doorstroming geblokkeerd (bijv. aquaductstenose, tumor); bij een <strong>communicerende</strong> de resorptie (na bloeding of meningitis). Bij zuigelingen groeit de schedelomtrek snel en is de fontanel bol; bij volwassenen ontstaan hoofdpijn, braken en sufheid. Normaledrukhydrocefalus geeft loopstoornis, incontinentie en dementie.</p>","image_url":"","wiki_title":"Hydrocephalus","match":"hydrocephalus|hydrocefalus|waterhoofd","option_only":true},"subarachnoïdale bloeding":{"title":"Subarachnoïdale bloeding (SAB)","short":"Een subarachnoïdale bloeding is een bloeding tussen de hersenvliezen, meestal door een gescheurd aneurysma, met plotselinge zeer hevige hoofdpijn.","definition":"<p>Een <strong>SAB</strong> geeft binnen seconden de ergste hoofdpijn ooit (‘donderslag’), vaak met braken, nekstijfheid en bewustzijnsdaling. Diagnose met CT, zo nodig gevolgd door een lumbaalpunctie (xanthochromie). Complicaties: nabloeding, vasospasme met infarcten en hydrocefalus. Het aneurysma wordt gecoild of geclipt.</p>","image_url":"","wiki_title":"Subarachnoid hemorrhage","match":"subarachnoïdale bloeding|sab|subarachnoidale bloeding","option_only":true},"ziekte van meniere":{"title":"Ziekte van Ménière","short":"De ziekte van Ménière geeft aanvallen van draaiduizeligheid met oorsuizen, een vol gevoel in het oor en schommelend gehoorverlies.","definition":"<p>Bij <strong>Ménière</strong> is er waarschijnlijk een ophoping van endolymfe in het binnenoor (endolymfatische hydrops). Aanvallen duren 20 minuten tot uren. Het gehoorverlies is aanvankelijk laagfrequent en wisselend, later blijvend. In late stadia kunnen otolietcrises van Tumarkin optreden.</p>","image_url":"","wiki_title":"Ménière's disease","match":"ziekte van meniere|ziekte van ménière|ménière","option_only":true},"macula-oedeem":{"title":"Maculopathie","short":"Maculopathie is een aandoening van de macula, het centrum van het netvlies, met verlies van het scherpe zien.","definition":"<p>Voorbeelden zijn leeftijdsgebonden maculadegeneratie, <strong>diabetisch maculaoedeem</strong> (lekkage uit beschadigde vaatjes), maculaoedeem na een veneuze occlusie of operatie, en erfelijke maculadystrofieën. Behandeling van oedeem vaak met anti-VEGF-injecties.</p>","image_url":"","wiki_title":"Macular edema","match":"macula-oedeem","option_only":true},"aortastenose":{"title":"Aortaklepstenose","short":"Bij aortaklepstenose opent de aortaklep onvoldoende, waardoor de linkerventrikel tegen verhoogde weerstand moet pompen.","definition":"<p><strong>Aortaklepstenose</strong> ontstaat meestal door degeneratieve verkalking op oudere leeftijd of bij een aangeboren bicuspide klep. De linkerventrikel hypertrofieert. Bij auscultatie is er een systolisch ejectiegeruis aan de basis, vaak uitstralend naar de carotiden. Klachten (angina, syncope bij inspanning, hartfalen) wijzen op een ernstige stenose; behandeling is klepvervanging (chirurgisch of TAVI).</p>","image_url":"","wiki_title":"Aortic stenosis","match":"aortastenose","option_only":true},"falx cerebri":{"title":"Falx cerebri","short":"De falx cerebri is een sikkelvormige plooi van de dura mater tussen de twee hersenhelften.","definition":"<p>In de bovenrand van de <strong>falx cerebri</strong> loopt de sinus sagittalis superior, in de onderrand de sinus sagittalis inferior. Een ruimte-innemend proces kan hersenweefsel onder de falx door duwen (subfalcine herniatie), met compressie van de a. cerebri anterior.</p>","image_url":"","wiki_title":"Falx cerebri","match":"falx cerebri","option_only":true},"tentorium cerebelli":{"title":"Tentorium cerebelli","short":"Het tentorium cerebelli is een tentvormige plooi van de dura mater tussen de grote hersenen en het cerebellum.","definition":"<p>Door de opening in het <strong>tentorium</strong> loopt de hersenstam. Bij verhoogde intracraniële druk kan de mediale temporaalkwab door deze opening worden geperst (transtentoriële herniatie), met compressie van de n. oculomotorius (wijde, lichtstijve pupil) en de hersenstam.</p>","image_url":"","wiki_title":"Cerebellar tentorium","match":"tentorium cerebelli","option_only":true},"confluens sinuum":{"title":"Confluens sinuum","short":"De confluens sinuum is de plek bij het achterhoofd waar de sinus sagittalis superior, sinus rectus en sinus occipitalis samenkomen.","definition":"<p>Vanuit de <strong>confluens sinuum</strong> voeren beide sinus transversi het bloed af naar de sinus sigmoidei en de vv. jugulares internae.</p>","image_url":"","wiki_title":"Confluence of sinuses","match":"confluens sinuum","option_only":true},"cisterna ambiens":{"title":"Cisterna ambiens","short":"De cisterna ambiens is een ruimte met liquor rond het mesencephalon.","definition":"<p>Op een CT van het hoofd is het verstrijken van de <strong>cisterna ambiens</strong> een teken van verhoogde intracraniële druk of dreigende herniatie.</p>","image_url":"","wiki_title":"Cisterna ambiens","match":"cisterna ambiens","option_only":true},"corpora mamillare":{"title":"Corpora mamillaria","short":"De corpora mamillaria zijn twee kleine kernen aan de onderkant van de hypothalamus, onderdeel van het circuit van Papez (geheugen).","definition":"<p>De <strong>corpora mamillaria</strong> ontvangen input via de fornix uit de hippocampus en projecteren naar de nucleus anterior van de thalamus. Bij thiaminetekort (Wernicke-Korsakov) raken ze beschadigd, met ernstige geheugenstoornissen.</p>","image_url":"","wiki_title":"Mammillary body","match":"corpora mamillare|corpora mamillaria","option_only":true},"putamen":{"title":"Putamen","short":"Het putamen is een kern van de basale ganglia die samen met de nucleus caudatus het striatum vormt.","definition":"<p>Het <strong>putamen</strong> ontvangt vooral input uit de motorische cortex en speelt een rol in de motoriek. Het ligt lateraal van de globus pallidus; samen heten ze de nucleus lentiformis. Hypertensieve bloedingen ontstaan vaak in het putamen.</p>","image_url":"","wiki_title":"Putamen","match":"putamen","option_only":true},"globus pallidus":{"title":"Globus pallidus","short":"De globus pallidus is een kern van de basale ganglia met een externe en interne kern, die vooral remmende (GABA-erge) output geeft.","definition":"<p>De <strong>globus pallidus interna</strong> is samen met de substantia nigra pars reticulata de uitgangskern van de basale ganglia; de externa is een schakel in de indirecte route.</p>","image_url":"","wiki_title":"Globus pallidus","match":"globus pallidus","option_only":true},"gyrus cinguli":{"title":"Gyrus cinguli","short":"De gyrus cinguli ligt boven het corpus callosum en speelt een rol bij emotie, motivatie, pijn en aandacht.","definition":"<p>De <strong>voorste cingulate cortex</strong> is betrokken bij foutdetectie, motivatie en de emotionele kant van pijn; laesies kunnen apathie en akinetisch mutisme geven.</p>","image_url":"","wiki_title":"Cingulate cortex","match":"gyrus cinguli|cingulate cortex","option_only":true},"gyrus parahippocampalis":{"title":"Gyrus parahippocampalis","short":"De gyrus parahippocampalis ligt aan de mediale onderkant van de temporaalkwab en is de belangrijkste toegangspoort naar de hippocampus.","definition":"<p>Het voorste deel, de entorhinale cortex, verbindt de neocortex met de hippocampus en is betrokken bij geheugen en ruimtelijke oriëntatie. Hier begint de ziekte van Alzheimer vaak.</p>","image_url":"","wiki_title":"Parahippocampal gyrus","match":"gyrus parahippocampalis|parahippocampale cortex","option_only":true},"gyrus calcarinus":{"title":"Sulcus calcarinus (primaire visuele cortex)","short":"Rond de sulcus calcarinus in de occipitaalkwab ligt de primaire visuele cortex.","definition":"<p>De <strong>primaire visuele cortex</strong> ontvangt via de radiatio optica informatie over de tegenovergestelde gezichtshelft. Een occipitaal infarct (a. cerebri posterior) geeft een homonieme hemianopsie, vaak met sparing van de macula.</p>","image_url":"","wiki_title":"Visual cortex","match":"gyrus calcarinus|sulcus calcarinus|primaire visuele cortex","option_only":true},"cellen van purkinje":{"title":"Purkinjecellen","short":"Purkinjecellen zijn grote neuronen in de cerebellaire cortex en de enige output van de cortex van het cerebellum (remmend, GABA-erg).","definition":"<p><strong>Purkinjecellen</strong> projecteren naar de diepe cerebellaire kernen. Ze zijn gevoelig voor alcohol, hypoxie en bepaalde erfelijke en paraneoplastische aandoeningen, die ataxie geven. In het hart verwijst de term ‘purkinjevezels’ naar het geleidingssysteem van de kamers.</p>","image_url":"","wiki_title":"Purkinje cell","match":"cellen van purkinje|purkinjecellen","option_only":true},"nucleus dentatus":{"title":"Nucleus dentatus","short":"De nucleus dentatus is de grootste diepe kern van het cerebellum en stuurt via de thalamus signalen naar de motorische cortex.","definition":"<p>Schade aan de <strong>nucleus dentatus</strong> of zijn uitgang (pedunculus cerebellaris superior) geeft ataxie en een intentietremor van de ledematen aan dezelfde kant.</p>","image_url":"","wiki_title":"Dentate nucleus","match":"nucleus dentatus","option_only":true},"pituïcyten":{"title":"Pituïcyten","short":"Pituïcyten zijn gliacellen in de hypofyseachterkwab, tussen de axonen die ADH en oxytocine afgeven.","definition":"<p>De hypofyseachterkwab bevat geen hormoonmakende cellen; ADH en oxytocine worden in de hypothalamus gemaakt. <strong>Pituïcyten</strong> ondersteunen de axonuiteinden en regelen mede de hormoonafgifte.</p>","image_url":"","wiki_title":"Pituicyte","match":"pituïcyten|pituicyten","option_only":true},"a. recurrens van heubner":{"title":"A. recurrens van Heubner","short":"De a. recurrens van Heubner is een tak van de a. cerebri anterior die delen van de basale kernen en de capsula interna voorziet.","definition":"<p>Een infarct in het gebied van de <strong>a. recurrens van Heubner</strong> kan een zwakte van gezicht en arm geven, omdat de kop van de nucleus caudatus en het voorste deel van de capsula interna betrokken zijn.</p>","image_url":"","wiki_title":"Recurrent artery of Heubner","match":"a. recurrens van heubner|arterie van heubner","option_only":true},"epineurium":{"title":"Epineurium","short":"Het epineurium is het bindweefsel rond een hele perifere zenuw; het perineurium omhult de bundels en het endoneurium de afzonderlijke axonen.","definition":"<p>Bij een zenuwhechting worden de lagen van het <strong>epineurium</strong> of perineurium aan elkaar gehecht. Het perineurium vormt een barrière (bloed-zenuwbarrière).</p>","image_url":"","wiki_title":"Epineurium","match":"epineurium|perineurium|endoneurium","option_only":true},"bitemporale hemianopsie":{"title":"Bitemporale hemianopsie","short":"Bij bitemporale hemianopsie vallen de buitenste (temporale) gezichtsvelden van beide ogen uit, door compressie van het chiasma opticum.","definition":"<p>In het chiasma kruisen de vezels van de nasale netvlieshelften, die het temporale gezichtsveld zien. Een <strong>bitemporale hemianopsie</strong> ontstaat daarom bij druk van onderaf (hypofyseadenoom) of bovenaf (craniofaryngioom).</p>","image_url":"","wiki_title":"Bitemporal hemianopsia","match":"bitemporale hemianopsie","option_only":true},"mouches volantes":{"title":"Mouches volantes","short":"Mouches volantes zijn zwevende vlekjes of draadjes in het gezichtsveld, door troebelingen in het glasvocht.","definition":"<p>Mouches volantes zijn meestal onschuldig. Een plotselinge toename, vooral met lichtflitsen of een schaduw, kan wijzen op een glasvochtloslating met netvliesscheur en vraagt om onderzoek.</p>","image_url":"","wiki_title":"Floater","match":"mouches volantes|glasvochttroebelingen|vliegjes","option_only":true},"amblyopie":{"title":"Amblyopie (lui oog)","short":"Amblyopie is een verminderd zicht van een oog door een ontwikkelingsstoornis in de visuele paden in de vroege kindertijd.","definition":"<p><strong>Amblyopie</strong> ontstaat door scheelzien, een groot sterkteverschil tussen de ogen of een obstakel (bijv. aangeboren staar). Behandeling met een bril en het afplakken van het goede oog werkt alleen op jonge leeftijd; daarom wordt kinderen het zicht gecontroleerd.</p>","image_url":"","wiki_title":"Amblyopia","match":"amblyopie|lui oog","option_only":true},"adl-schaal":{"title":"ADL-schaal","short":"ADL-schalen meten hoe zelfstandig iemand dagelijkse activiteiten uitvoert, zoals wassen en aankleden (ADL) of huishouden en financiën (IADL).","definition":"<p>Een bekende ADL-schaal is de <strong>Barthel-index</strong>; voor instrumentele activiteiten (IADL) de Lawton-schaal. Ze worden o.a. in de geriatrie en revalidatie gebruikt om functieverlies vast te stellen en te volgen.</p>","image_url":"","wiki_title":"Activities of daily living","match":"adl-schaal|adl|iadl-schaal|iadl","option_only":true},"jij-boodschap":{"title":"Jij-boodschap","short":"Een jij-boodschap legt de nadruk op het gedrag van de ander (‘jij doet altijd…’) en roept vaak verdediging op.","definition":"<p>Bij weerstand of conflict is een <strong>ik-boodschap</strong> (vanuit de eigen ervaring) meestal effectiever dan een jij-boodschap, omdat die minder beschuldigend overkomt.</p>","image_url":"","wiki_title":"","match":"jij-boodschap","option_only":true},"nervus abducens parese":{"title":"N. abducens (VI)","short":"De n. abducens (VI) innerveert de m. rectus lateralis, die het oog naar buiten beweegt.","definition":"<p>De <strong>n. abducens</strong> ontspringt aan de grens van pons en medulla en heeft een lang intracraniëel verloop, door de sinus cavernosus naar de orbita. Daardoor is hij gevoelig voor verhoogde intracraniële druk. Uitval geeft horizontale dubbelbeelden en een oog dat niet goed naar buiten kan bewegen.</p>","image_url":"","wiki_title":"Abducens nerve","match":"nervus abducens parese","option_only":true},"creatinekinase verhoging":{"title":"Creatinekinase (CK)","short":"Creatinekinase is een enzym uit spieren; een verhoogde bloedwaarde wijst op spierschade.","definition":"<p><strong>CK</strong> zet creatinefosfaat en ADP om in creatine en ATP. Het stijgt bij spierschade: rabdomyolyse, myositis, spierdystrofieën, na intensieve inspanning, trauma of injecties, en door statines. De CK-MB-vorm werd vroeger gebruikt bij hartinfarcten.</p>","image_url":"","wiki_title":"Creatine kinase","match":"creatinekinase verhoging","option_only":true},"calorische nystagmus":{"title":"Calorische test","short":"Bij de calorische test wordt de gehoorgang gespoeld met warm of koud water, wat via het evenwichtsorgaan een nystagmus opwekt.","definition":"<p>Met koud water slaat de snelle fase van de nystagmus naar de andere kant, met warm water naar dezelfde kant (ezelsbrug ‘COWS’). Een verminderde reactie aan één kant wijst op uitval van dat evenwichtsorgaan (bijv. neuritis vestibularis). Bij comateuze patiënten test de koudwaterproef de hersenstam.</p>","image_url":"","wiki_title":"Caloric reflex test","match":"calorische nystagmus|calorische test|calorische prikkeling","option_only":true},"arteria communicans posterior":{"title":"A. communicans posterior","short":"De a. communicans posterior verbindt de a. carotis interna met de a. cerebri posterior, als deel van de cirkel van Willis.","definition":"<p>Een aneurysma van de <strong>a. communicans posterior</strong> kan de n. oculomotorius samendrukken, met een ptosis en een wijde, lichtstijve pupil. Bij zo'n acuut ontstane derde-zenuwparese met pupilbetrokkenheid moet een aneurysma worden uitgesloten.</p>","image_url":"","wiki_title":"Posterior communicating artery","match":"arteria communicans posterior|a. communicans posterior","option_only":true},"oligodendrocyten":{"title":"Oligodendrocyten","short":"Oligodendrocyten zijn gliacellen die de myelineschede rond axonen in het centrale zenuwstelsel maken.","definition":"<p>Eén <strong>oligodendrocyt</strong> kan meerdere axonen myeliniseren. Bij multiple sclerose worden de myeline en oligodendrocyten aangevallen.</p>","image_url":"","wiki_title":"Oligodendrocyte","match":"oligodendrocyten|oligodendrocyt","option_only":true},"oligodendrocyt":{"title":"Oligodendrocyten","short":"Oligodendrocyten zijn gliacellen die de myelineschede rond axonen in het centrale zenuwstelsel maken.","definition":"<p>Eén <strong>oligodendrocyt</strong> kan meerdere axonen myeliniseren. Bij multiple sclerose worden de myeline en oligodendrocyten aangevallen.</p>","image_url":"","wiki_title":"Oligodendrocyte","match":"oligodendrocyt","option_only":true},"migraine":{"title":"Migraine","short":"Aanvalsgewijze, vaak eenzijdige kloppende hoofdpijn met misselijkheid, foto- en fonofobie, soms met aura. Duurt uren tot een dag.","definition":"<p><b>Migraine</b>-aanvallen worden verergerd door inspanning; de patiënt zoekt rust in een donkere kamer. Aanvalsbehandeling met triptanen bij onvoldoende effect van NSAID's.</p>","image_url":"","wiki_title":"Migraine","match":"migraine","option_only":true},"arachnoïdale villi":{"title":"Arachnoïdale granulaties","short":"Arachnoïdale granulaties zijn uitstulpingen van de arachnoidea in de durale sinussen, waarlangs liquor naar het veneuze bloed wordt afgevoerd.","definition":"<p>Via de <strong>arachnoïdale granulaties</strong> (vooral in de sinus sagittalis superior) wordt liquor geresorbeerd. Bij een verstoorde resorptie (bijv. na een subarachnoïdale bloeding of meningitis) kan een communicerende hydrocephalus ontstaan.</p>","image_url":"","wiki_title":"Arachnoid granulation","match":"arachnoïdale villi","option_only":true},"verhoogde oogboldruk (glaucoom)":{"title":"Glaucoom","short":"Beschadiging van de oogzenuw, vaak door verhoogde oogdruk, met blijvend gezichtsvelduitval.","definition":"<p>Glaucoom is een progressieve beschadiging van de nervus opticus, vaak samenhangend met een verhoogde oogboldruk. Het veroorzaakt onomkeerbare gezichtsvelduitval en kan onbehandeld tot blindheid leiden.</p>","image_url":"","wiki_title":"Glaucoma","match":"verhoogde oogboldruk (glaucoom)","option_only":true},"repolarisatie":{"title":"Repolarisatie","short":"Herstel van de rustpotentiaal van hartspiercellen na een contractie; op het ECG zichtbaar als de T-top (ventrikels).","definition":"<p>Na depolarisatie herstellen de myocardcellen hun membraanpotentiaal (repolarisatie). Ventriculaire repolarisatie komt op het ECG overeen met de T-top.</p>","image_url":"","wiki_title":"Repolarization","match":"repolarisatie","option_only":true},"substantia nigra":{"title":"Substantia nigra","short":"Dopaminerge kern in het mesencephalon, deel van de basale ganglia.","definition":"<p>De <b>substantia nigra</b> zendt dopaminerge projecties naar het striatum; degeneratie leidt tot de ziekte van Parkinson.</p>","image_url":"","wiki_title":"Substantia nigra","match":"substantia nigra","option_only":true},"pons":{"title":"Pons","short":"De brug; deel van de hersenstam tussen mesencephalon en myelencephalon.","definition":"<p>De <b>pons</b> bevat kernen en banen die grote en kleine hersenen verbinden en o.a. de n. trigeminus, abducens en facialis herbergen.</p>","image_url":"","wiki_title":"Pons","match":"pons","option_only":true},"nasale hemianopsie":{"title":"Nasale hemianopsie","short":"Uitval van de nasale (mediale) helft van het gezichtsveld van één oog, o.a. door druk op de laterale zijde van het chiasma.","definition":"<p>Een <b>nasale hemianopsie</b> kan ontstaan bij bijvoorbeeld een aneurysma van de arteria carotis interna dat op de laterale vezels van het chiasma drukt.</p>","image_url":"","wiki_title":"Hemianopsia","match":"nasale hemianopsie","option_only":true},"klassieke conditionering":{"title":"Klassieke conditionering","short":"Leren door associatie tussen een neutrale en een betekenisvolle prikkel.","definition":"<p><b>Klassieke conditionering</b> (Pavlov) is een impliciete leervorm waarbij een neutrale stimulus een geconditioneerde respons gaat oproepen.</p>","image_url":"","wiki_title":"Classical conditioning","match":"klassieke conditionering","option_only":true},"priming":{"title":"Priming","short":"Onbewuste beïnvloeding van een reactie door een eerdere stimulus.","definition":"<p><b>Priming</b> is een vorm van impliciet geheugen waarbij blootstelling aan een prikkel latere verwerking van een verwante prikkel versnelt.</p>","image_url":"","wiki_title":"Priming (psychology)","match":"priming","option_only":true},"benigne paroxismale positieduizeligheid (bppd)":{"title":"BPPD","short":"Benigne paroxysmale positieduizeligheid: kortdurende draaiduizeligheid uitgelokt door hoofdbewegingen, door losgeraakte otolieten in een halfcirkelvormig kanaal.","definition":"<p><b>BPPD</b> (benigne paroxysmale positieduizeligheid) wordt veroorzaakt door otolietgruis (canalithiasis) in meestal het posterieure semicirculaire kanaal. Kenmerkend is kortdurende vertigo uitgelokt door standsverandering van het hoofd; de Dix-Hallpike-test is positief.</p>","image_url":"","wiki_title":"Benign paroxysmal positional vertigo","match":"benigne paroxismale positieduizeligheid (bppd)","option_only":true},"cataract":{"title":"Cataract","short":"Vertroebeling van de ooglens (staar), een behandelbare (reversibele) oorzaak van slechtziendheid.","definition":"<p>Cataract (staar) is een vertroebeling van de ooglens, waardoor het zicht geleidelijk verslechtert. Het is de meest voorkomende, maar goed behandelbare (reversibele) oorzaak van slechtziendheid; een staaroperatie herstelt het zicht.</p>","image_url":"","wiki_title":"Cataract","match":"cataract","option_only":true},"metamorfopsie":{"title":"Metamorfopsie","short":"Vervormd zien van rechte lijnen; klassiek symptoom van maculapathologie.","definition":"<p><b>Metamorfopsie</b> is het waarnemen van rechte lijnen als golvend of vervormd, opgespoord met het Amslerkaartje.</p>","image_url":"","wiki_title":"Metamorphopsia","match":"metamorfopsie","option_only":true},"n infraorbitalis":{"title":"N. infraorbitalis","short":"De n. infraorbitalis is een tak van de n. maxillaris (V2) die de huid van wang, onderooglid, zijkant neus en bovenlip verzorgt.","definition":"<p>De <strong>n. infraorbitalis</strong> loopt over de orbitabodem door de canalis infraorbitalis en komt via het foramen infraorbitale op het gezicht. Bij een orbitabodemfractuur (blow-out) kan de zenuw beschadigd raken, met gevoelloosheid van wang en bovenlip als gevolg.</p>","image_url":"","wiki_title":"Infraorbital nerve","match":"n infraorbitalis","option_only":true},"schwann cel":{"title":"Schwann-cel","short":"Gliacel die myeline vormt in het perifere zenuwstelsel.","definition":"<p>De <b>Schwann-cel</b> myeliniseert axonen buiten het centrale zenuwstelsel (perifere zenuwen).</p>","image_url":"","wiki_title":"Schwann cell","match":"schwann cel","option_only":true},"cingulaire cortex":{"title":"Cingulaire cortex","short":"Deel van de mediale cortex, betrokken bij emotie en het limbische systeem.","definition":"<p>De <b>cingulaire cortex</b> ligt boven het corpus callosum en maakt deel uit van het limbische systeem.</p>","image_url":"","wiki_title":"Cingulate cortex","match":"cingulaire cortex","option_only":true},"cognitieve functies":{"title":"Cognitieve functies","short":"Verstandelijke functies zoals bewustzijn, aandacht, geheugen, denken en concentratie.","definition":"<p><b>Cognitieve functies</b> omvatten onder meer bewustzijn, oriëntatie, aandacht, concentratie, geheugen en het denken. Stoornissen hierin uiten zich bijvoorbeeld als verminderde concentratie of piekeren.</p>","image_url":"","wiki_title":"","match":"cognitieve functies","option_only":true},"affectieve functies":{"title":"Affectieve functies","short":"Functies die de stemming en gevoelens betreffen, zoals angst, somberheid en stemmingsschommelingen.","definition":"<p><b>Affectieve functies</b> betreffen de stemming en het gevoelsleven. Stoornissen hierin uiten zich als bijvoorbeeld angstige of sombere stemming, lusteloosheid of een labiel affect.</p>","image_url":"","wiki_title":"","match":"affectieve functies","option_only":true},"commisura anterior":{"title":"Commissura anterior","short":"Kleine witte-stofbundel die o.a. de temporaalkwabben en reukgebieden verbindt.","definition":"<p>De <b>commissura anterior</b> verbindt onder meer de amygdala en de tractus olfactorius van beide zijden.</p>","image_url":"","wiki_title":"Anterior commissure","match":"commisura anterior","option_only":true},"floaters":{"title":"Mouches volantes","short":"Mouches volantes zijn zwevende vlekjes of draadjes in het gezichtsveld, door troebelingen in het glasvocht.","definition":"<p>Mouches volantes zijn meestal onschuldig. Een plotselinge toename, vooral met lichtflitsen of een schaduw, kan wijzen op een glasvochtloslating met netvliesscheur en vraagt om onderzoek.</p>","image_url":"","wiki_title":"Floater","match":"floaters","option_only":true},"vitamine b12 suppletie":{"title":"Vitamine B12-deficiëntie","short":"Een vitamine B12-tekort geeft een macrocytaire anemie en neurologische schade, zoals polyneuropathie en een gecombineerde strengziekte.","definition":"<p>Oorzaken van een <strong>B12-tekort</strong> zijn auto-immuungastritis (pernicieuze anemie, antistoffen tegen intrinsieke factor), maag- of ileumresectie, ziekte van Crohn, metformine, langdurig PPI-gebruik en veganistisch eten. Naast anemie ontstaan neuropathie, degeneratie van achterstrengen en piramidebanen, cognitieve stoornissen en glossitis. Methylmalonzuur en homocysteïne zijn verhoogd.</p>","image_url":"","wiki_title":"Vitamin B12 deficiency","match":"vitamine b12 suppletie","option_only":true},"arterosclerose":{"title":"Atherosclerose","short":"Atherosclerose is een chronisch ontstekingsproces in de vaatwand waarbij plaques met vet, ontstekingscellen en bindweefsel ontstaan.","definition":"<p>Bij <strong>atherosclerose</strong> dringt LDL de intima binnen en wordt het geoxideerd; monocyten worden macrofagen en schuimcellen (fatty streak). Gladde spiercellen migreren en vormen een fibreuze kap over een lipidenkern. Scheuren van een plaque met trombose veroorzaakt een acuut coronair syndroom of herseninfarct. Risicofactoren: roken, hypertensie, LDL, diabetes, leeftijd en familiaire belasting.</p>","image_url":"","wiki_title":"Atherosclerosis","match":"arterosclerose","option_only":true},"rolandische epilepsie":{"title":"Rolandische epilepsie (benigne epilepsie met centrotemporale pieken)","short":"Rolandische epilepsie is een goedaardige kinderepilepsie met aanvallen tijdens de slaap, waarbij één kant van gezicht en mond trekt en het kind niet kan praten.","definition":"<p>De aanvallen beginnen tussen 3 en 13 jaar en verdwijnen meestal in de puberteit. Het EEG toont centrotemporale pieken, vooral tijdens de slaap. Behandeling is vaak niet nodig.</p>","image_url":"","wiki_title":"Benign Rolandic epilepsy","match":"rolandische epilepsie|benigne rolandische epilepsie|selflimited epilepsy with centrotemporal spikes","option_only":true},"lennox-gastaut syndroom":{"title":"Syndroom van Lennox-Gastaut","short":"Lennox-Gastaut is een ernstig epilepsiesyndroom bij kinderen met meerdere aanvalstypen (vooral tonische aanvallen en valaanvallen) en een verstandelijke beperking.","definition":"<p>Het EEG toont trage piek-golfcomplexen. Het syndroom kan ontstaan na het syndroom van West. De aanvallen zijn vaak moeilijk te behandelen; middelen zijn o.a. valproaat, lamotrigine, rufinamide en clobazam, soms een ketogeen dieet of nervus vagusstimulatie.</p>","image_url":"","wiki_title":"Lennox–Gastaut syndrome","match":"lennox-gastaut syndroom|syndroom van lennox-gastaut|syndroom van lennox-gastaux","option_only":true},"chronische slapeloosheid":{"title":"Insomnie","short":"Insomnie is moeite met in- of doorslapen of te vroeg wakker worden, minstens drie nachten per week gedurende drie maanden, met klachten overdag.","definition":"<p>De eerste keus bij <strong>chronische insomnie</strong> is CGT voor insomnie (slaaprestrictie, stimuluscontrole, slaaphygiëne, cognitieve technieken). Slaapmiddelen zijn alleen kortdurend zinvol, vanwege gewenning, afhankelijkheid en valrisico.</p>","image_url":"","wiki_title":"Insomnia","match":"chronische slapeloosheid|insomnie|slapeloosheid","option_only":true},"ganglion cellen":{"title":"Cellen van de retina","short":"Het netvlies bevat lagen van fotoreceptoren, bipolaire cellen en ganglioncellen, met horizontale en amacriene cellen als tussenschakels.","definition":"<p>Licht wordt door <strong>staafjes en kegeltjes</strong> omgezet in een signaal, dat via bipolaire cellen naar de <strong>ganglioncellen</strong> gaat; hun axonen vormen de n. opticus. Bij glaucoom gaan vooral ganglioncellen verloren.</p>","image_url":"","wiki_title":"Retina","match":"ganglion cellen|ganglioncellen|bipolaire cellen|amacriene cellen|zintuig cellen","option_only":true},"neuritis van de n. opticus":{"title":"Neuritis optica","short":"Neuritis optica is een ontsteking van de oogzenuw met pijn bij oogbewegingen, verminderd zicht en een verminderd kleurenzien.","definition":"<p><strong>Neuritis optica</strong> komt vooral bij jonge vrouwen voor en kan het eerste teken van MS zijn. Er is een relatief afferent pupildefect. Het zicht herstelt meestal binnen weken tot maanden; hoge dosis corticosteroïden versnelt het herstel.</p>","image_url":"","wiki_title":"Optic neuritis","match":"neuritis van de n. opticus|neuritis optica","option_only":true},"afsluiting van de v. centralis retinae":{"title":"Centrale veneuze occlusie","short":"Bij een afsluiting van de v. centralis retinae ontstaan plotseling pijnloos zichtverlies en veel bloedingen in het hele netvlies.","definition":"<p>Risicofactoren zijn hypertensie, diabetes, glaucoom en hoge leeftijd. Complicaties zijn maculaoedeem en neovasculair glaucoom; behandeling met anti-VEGF-injecties en zo nodig laser.</p>","image_url":"","wiki_title":"Central retinal vein occlusion","match":"afsluiting van de v. centralis retinae|centrale veneuze occlusie|crvo","option_only":true},"homonieme hemianopsie in het onderste kwadrant":{"title":"Gezichtsvelduitval","short":"Het patroon van gezichtsvelduitval verraadt de plaats van de laesie in de visuele baan.","definition":"<p>Achter het chiasma geven laesies een <strong>homonieme</strong> uitval naar de andere kant. Laesies in de temporaalkwab (lus van Meyer) geven een uitval in het bovenkwadrant, in de pariëtaalkwab een uitval in het onderkwadrant.</p>","image_url":"","wiki_title":"Visual field","match":"homonieme hemianopsie in het onderste kwadrant|homonieme hemianopsie in het bovenste kwadrant|binasale hemianopsie|homonieme hemianopsie|quadrantanopsie","option_only":true}};
